insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('160ff92c-006f-54e2-b81d-bea06a3ad99c', 'aaaaaaaa-0000-0000-0000-000000000007', '134', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَرَادَ أَنْ يَتَّخِذَ خَشَبَتَيْنِ يُضْرَبُ بِهِمَا لِيَجْتَمِعَ النَّاسُ لِلصَّلَاةِ فَأُرِيَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ الْأَنْصَارِيُّ ‏ ‏ثُمَّ مِنْ ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏خَشَبَتَيْنِ فِي النَّوْمِ فَقَالَ إِنَّ هَاتَيْنِ لَنَحْوٌ مِمَّا يُرِيدُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ أَلَا تُؤَذِّنُونَ لِلصَّلَاةِ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ اسْتَيْقَظَ فَذَكَرَ لَهُ ذَلِكَ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْأَذَانِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c11a366c-5008-5dfa-a3c8-08260a786e29', 'aaaaaaaa-0000-0000-0000-000000000007', '135', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ النِّدَاءَ فَقُولُوا مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('75bb81bc-72a4-5fa1-a2de-9e96fe3acca3', 'aaaaaaaa-0000-0000-0000-000000000007', '136', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ ‏ ‏يَسْتَهِمُوا ‏ ‏عَلَيْهِ لَاسْتَهَمُوا وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا إِلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ حَبْوًا ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0b2d5140-e464-59e0-9df7-c75758de7d92', 'aaaaaaaa-0000-0000-0000-000000000007', '137', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَإِسْحَقَ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُمَا أَخْبَرَاهُ أَنَّهُمَا سَمِعَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ فَلَا تَأْتُوهَا وَأَنْتُمْ تَسْعَوْنَ وَأْتُوهَا وَعَلَيْكُمْ السَّكِينَةُ فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا فَإِنَّ أَحَدَكُمْ فِي صَلَاةٍ مَا كَانَ يَعْمِدُ إِلَى الصَّلَاةِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5651d3a5-5a6c-563d-9b90-0fe4595e517e', 'aaaaaaaa-0000-0000-0000-000000000007', '138', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ الْأَنْصَارِيِّ ثُمَّ الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ أَخْبَرَهُ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ لَهُ ‏ ‏إِنِّي أَرَاكَ تُحِبُّ الْغَنَمَ وَالْبَادِيَةَ فَإِذَا كُنْتَ فِي غَنَمِكَ أَوْ بَادِيَتِكَ فَأَذَّنْتَ بِالصَّلَاةِ فَارْفَعْ صَوْتَكَ بِالنِّدَاءِ فَإِنَّهُ لَا يَسْمَعُ مَدَى صَوْتِ الْمُؤَذِّنِ جِنٌّ وَلَا إِنْسٌ وَلَا شَيْءٌ إِلَّا شَهِدَ لَهُ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f3ab7cc9-4231-5b5f-98cb-f6d65ca53e88', 'aaaaaaaa-0000-0000-0000-000000000007', '139', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ أَدْبَرَ الشَّيْطَانُ لَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ النِّدَاءَ فَإِذَا قُضِيَ النِّدَاءُ أَقْبَلَ حَتَّى إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ أَدْبَرَ حَتَّى إِذَا قُضِيَ التَّثْوِيبُ أَقْبَلَ حَتَّى ‏ ‏يَخْطِرَ ‏ ‏بَيْنَ الْمَرْءِ وَنَفْسِهِ يَقُولُ اذْكُرْ كَذَا اذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ حَتَّى يَظَلَّ الرَّجُلُ إِنْ يَدْرِي كَمْ صَلَّى ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('21a14505-a050-5536-b8e9-77906c946b00', 'aaaaaaaa-0000-0000-0000-000000000007', '140', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏أَبِي حَازِمِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَاعَتَانِ يُفْتَحُ لَهُمَا أَبْوَابُ السَّمَاءِ وَقَلَّ دَاعٍ تُرَدُّ عَلَيْهِ دَعْوَتُهُ حَضْرَةُ النِّدَاءِ لِلصَّلَاةِ وَالصَّفُّ فِي سَبِيلِ اللَّهِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('492b798d-14c5-5599-9e95-dbd830465573', 'aaaaaaaa-0000-0000-0000-000000000007', '141', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي سُهَيْلِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا أَعْرِفُ شَيْئًا مِمَّا أَدْرَكْتُ عَلَيْهِ النَّاسَ إِلَّا النِّدَاءَ بِالصَّلَاةِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('17a684e3-b742-53e6-bac7-e5ac2032b3c4', 'aaaaaaaa-0000-0000-0000-000000000007', '142', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏سَمِعَ الْإِقَامَةَ وَهُوَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَأَسْرَعَ الْمَشْيَ إِلَى الْمَسْجِدِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
