insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a5af7242-6ccd-5029-90fd-410f37741efd', 'aaaaaaaa-0000-0000-0000-000000000007', '145', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏قَالَ لَهُ ‏ ‏إِذَا كُنْتَ فِي سَفَرٍ فَإِنْ شِئْتَ أَنْ تُؤَذِّنَ وَتُقِيمَ فَعَلْتَ وَإِنْ شِئْتَ فَأَقِمْ وَلَا تُؤَذِّنْ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏سَمِعْت ‏ ‏قَوْله تَعَالَى ‏ ‏يَقُولُ لَا بَأْسَ أَنْ يُؤَذِّنَ الرَّجُلُ وَهُوَ رَاكِبٌ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
