insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eb0c0afa-7ca3-5a64-a391-68cfdbad0f0f', 'aaaaaaaa-0000-0000-0000-000000000007', '168', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ الصِّدِّيقَ ‏ ‏صَلَّى الصُّبْحَ فَقَرَأَ فِيهَا سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏فِي الرَّكْعَتَيْنِ كِلْتَيْهِمَا ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
