insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9851b75c-ad7a-5b44-a927-0194abe5e259', 'aaaaaaaa-0000-0000-0000-000000000007', '177', '‏ ‏و حَدَّثَنِي ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ رُومَانَ ‏ ‏أَنَّ ‏ ‏نَافِعَ بْنَ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏كَانَ ‏ ‏يَقْرَأُ خَلْفَ الْإِمَامِ فِيمَا لَا يَجْهَرُ فِيهِ بِالْقِرَاءَةِ ‏ ‏قَالَ ‏ ‏مَالِك ‏ ‏وَذَلِكَ أَحَبُّ مَا سَمِعْتُ إِلَيَّ فِي ذَلِكَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eba682ab-68f8-5273-ad6c-d77c3d5b346a', 'aaaaaaaa-0000-0000-0000-000000000007', '178', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏كَانَ إِذَا سُئِلَ هَلْ يَقْرَأُ أَحَدٌ خَلْفَ الْإِمَامِ قَالَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ خَلْفَ الْإِمَامِ فَحَسْبُهُ قِرَاءَةُ الْإِمَامِ وَإِذَا صَلَّى وَحْدَهُ فَلْيَقْرَأْ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏لَا يَقْرَأُ خَلْفَ الْإِمَامِ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('634604ba-fb0d-5129-be7b-9f64a5396c53', 'aaaaaaaa-0000-0000-0000-000000000007', '179', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏ابْنِ أُكَيْمَةَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْصَرَفَ مِنْ صَلَاةٍ جَهَرَ فِيهَا بِالْقِرَاءَةِ فَقَالَ ‏ ‏هَلْ قَرَأَ مَعِي مِنْكُمْ أَحَدٌ آنِفًا فَقَالَ رَجُلٌ نَعَمْ أَنَا يَا رَسُولَ اللَّهِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَقُولُ مَا لِي ‏ ‏أُنَازَعُ الْقُرْآنَ ‏ ‏فَانْتَهَى النَّاسُ عَنْ الْقِرَاءَةِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا جَهَرَ فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْقِرَاءَةِ حِينَ سَمِعُوا ذَلِكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be453cf5-9203-503f-827e-882c16c1af1f', 'aaaaaaaa-0000-0000-0000-000000000007', '180', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مَالِك ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُمَا أَخْبَرَاهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَمَّنَ الْإِمَامُ فَأَمِّنُوا فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ آمِينَ ‏', 'موطأ الإمام مالك — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadith_books (id, slug, name_ar, name_en, source, author_ar, author_en, hadith_count) values ('aaaaaaaa-0000-0000-0000-000000000008', 'ahmad', 'مسند أحمد', 'Musnad Ahmad', 'Open-Hadith-Data (ODbL/DbCL)', 'الإمام أحمد', 'Imam Ahmad', 26363) on conflict (slug) do update set name_ar=excluded.name_ar, name_en=excluded.name_en, source=excluded.source, author_ar=excluded.author_ar, author_en=excluded.author_en, hadith_count=excluded.hadith_count;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8d90c45b-572d-5846-94a3-a1d722f100ec', 'aaaaaaaa-0000-0000-0000-000000000008', '1', 'حدثنا  عبد الله بن نمير  قال أخبرنا  إسماعيل يعني ابن أبي خالد  عن  قيس  قال  قام  أبو بكر  رضي الله عنه  فحمد الله وأثنى عليه ثم قال يا أيها الناس إنكم تقرءون هذه الآية  { يا أيها الذين آمنوا عليكم أنفسكم لا يضركم من ضل إذا اهتديتم } وإنا سمعنا رسول الله  صلى الله عليه وسلم  يقول  إن الناس إذا رأوا المنكر فلم  ينكروه  أوشك  أن يعمهم الله بعقابه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('431bc082-c503-5548-83e6-456a39d4f3e4', 'aaaaaaaa-0000-0000-0000-000000000008', '2', 'حدثنا  وكيع  قال حدثنا  مسعر  وسفيان  عن  عثمان بن المغيرة الثقفي  عن  علي بن ربيعة الوالبي  عن  أسماء بن الحكم الفزاري  عن  علي  رضي الله عنه  قال  كنت إذا سمعت من رسول الله  صلى الله عليه وسلم  حديثا نفعني الله بما شاء منه وإذا حدثني عنه غيري استحلفته فإذا حلف لي صدقته وإن  أبا بكر  رضي الله عنه  حدثني وصدق  أبو بكر  أنه سمع النبي  صلى الله عليه وسلم  قال  ما من رجل يذنب ذنبا فيتوضأ فيحسن الوضوء  قال  مسعر  ويصلي  وقال  سفيان  ثم  يصلي  ركعتين فيستغفر الله عز وجل إلا غفر له', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b5028c2-2494-5077-8eda-18539a9498eb', 'aaaaaaaa-0000-0000-0000-000000000008', '3', 'حدثنا  عمرو بن محمد أبو سعيد يعني العنقزي  قال حدثنا  إسرائيل  عن  أبي إسحاق  عن  البراء بن عازب  قال  اشترى  أبو بكر  من  عازب  سرجا بثلاثة عشر درهما قال فقال  أبو بكر  لعازب  مر  البراء  فليحمله إلى منزلي فقال لا حتى تحدثنا كيف صنعت حين خرج رسول الله  صلى الله عليه وسلم  وأنت معه قال فقال  أبو بكر  خرجنا  فأدلجنا  فأحثثنا  يومنا وليلتنا حتى أظهرنا وقام قائم الظهيرة  فضربت  ببصري هل أرى ظلا  نأوي إليه فإذا أنا بصخرة فأهويت إليها فإذا بقية ظلها فسويته لرسول الله  صلى الله عليه وسلم  وفرشت له فروة وقلت اضطجع يا رسول الله فاضطجع ثم خرجت أنظر هل أرى أحدا من  الطلب  فإذا أنا  براعي غنم فقلت لمن أنت يا غلام فقال لرجل من  قريش  فسماه فعرفته فقلت هل في غنمك من لبن قال نعم قال قلت هل أنت حالب لي قال نعم قال فأمرته  فاعتقل  شاة منها ثم أمرته فنفض ضرعها من الغبار ثم أمرته فنفض كفيه من الغبار ومعي  إداوة  على فمها خرقة فحلب لي  كثبة  من اللبن  فصببت  يعني الماء على القدح حتى  برد  أسفله ثم أتيت رسول الله  صلى الله عليه وسلم  فوافيته وقد استيقظ فقلت اشرب يا رسول الله فشرب حتى رضيت ثم قلت هل أنى الرحيل قال فارتحلنا والقوم يطلبونا فلم يدركنا أحد منهم إلا  سراقة بن مالك بن جعشم  على فرس له فقلت يا رسول الله هذا  الطلب  قد لحقنا فقال لا تحزن إن الله معنا حتى إذا دنا منا فكان بيننا وبينه قدر رمح  أو رمحين أو ثلاثة  قال قلت يا رسول الله هذا  الطلب  قد لحقنا وبكيت قال لم تبكي قال قلت أما والله ما على نفسي أبكي ولكن أبكي عليك قال فدعا عليه رسول الله  صلى الله عليه وسلم  فقال  اللهم اكفناه بما شئت  فساخت  قوائم فرسه إلى بطنها في أرض صلد ووثب عنها وقال يا  محمد  قد علمت أن هذا عملك فادع الله أن ينجيني مما أنا فيه فوالله  لأعمين  على من ورائي من  الطلب  وهذه  كنانتي  فخذ منها سهما فإنك ستمر بإبلي وغنمي في موضع كذا وكذا فخذ منها حاجتك قال فقال رسول الله  صلى الله عليه وسلم  لا حاجة لي فيها قال ودعا له رسول الله  صلى الله عليه وسلم  فأطلق فرجع إلى أصحابه ومضى رسول الله  صلى الله عليه وسلم  وأنا معه حتى قدمنا  المدينة  فتلقاه الناس فخرجوا في الطريق وعلى  الأجاجير  فاشتد  الخدم والصبيان في الطريق يقولون الله أكبر جاء رسول الله  صلى الله عليه وسلم  جاء  محمد  قال وتنازع القوم أيهم ينزل عليه قال فقال رسول الله  صلى الله عليه وسلم  أنزل الليلة على  بني النجار  أخوال  عبد المطلب  لأكرمهم بذلك فلما أصبح  غدا  حيث أمر قال  البراء بن عازب  أول من كان قدم علينا من  المهاجرين  مصعب بن عمير  أخو  بني عبد الدار  ثم قدم علينا  ابن أم مكتوم الأعمى  أخو  بني فهر  ثم قدم علينا  عمر بن الخطاب  في عشرين راكبا فقلنا ما فعل رسول الله  صلى الله عليه وسلم  فقال هو على أثري ثم قدم رسول الله  صلى الله عليه وسلم  وأبو بكر  معه قال  البراء  ولم يقدم رسول الله  صلى الله عليه وسلم  حتى  حفظت  سورا من  المفصل  قال  إسرائيل  وكان  البراء  من  الأنصار  من  بني حارثة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d69fabef-c496-549e-a7f4-28042048dccf', 'aaaaaaaa-0000-0000-0000-000000000008', '4', 'حدثنا  وكيع  قال قال  إسرائيل  قال  أبو إسحاق  عن  زيد بن يثيع  عن  أبي بكر  أن النبي  صلى الله عليه وسلم  بعثه  ببراءة  لأهل  مكة  لا يحج بعد العام مشرك ولا يطوف  بالبيت  عريان ولا يدخل الجنة إلا نفس مسلمة من كان بينه وبين رسول الله  صلى الله عليه وسلم  مدة  فأجله إلى  مدته  والله بريء من المشركين ورسوله قال فسار بها ثلاثا ثم قال  لعلي  رضي الله تعالى عنه  الحقه  فرد  علي  أبا بكر  وبلغها أنت قال ففعل قال فلما قدم على النبي  صلى الله عليه وسلم  أبو بكر  بكى قال يا رسول الله حدث في شيء قال ما حدث فيك إلا خير ولكن أمرت أن لا يبلغه إلا أنا أو رجل مني', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3d7dd419-0058-58d1-b95d-2bcc3d87de62', 'aaaaaaaa-0000-0000-0000-000000000008', '5', 'حدثنا  محمد بن جعفر  قال حدثنا  شعبة  عن  يزيد بن خمير  عن  سليم بن عامر  عن  أوسط  قال  خطبنا  أبو بكر  رضي الله عنه  فقال قام رسول الله  صلى الله عليه وسلم  مقامي هذا عام الأول وبكى  أبو بكر  فقال  أبو بكر  سلوا الله المعافاة  أو قال  العافية  فلم يؤت أحد قط بعد اليقين أفضل من العافية  أو المعافاة  عليكم بالصدق فإنه مع البر وهما في الجنة وإياكم والكذب فإنه مع الفجور وهما في النار ولا تحاسدوا ولا تباغضوا ولا تقاطعوا ولا تدابروا وكونوا إخوانا كما أمركم الله تعالى', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3a3798c2-3fbb-5ec2-9bc9-c3021090a13a', 'aaaaaaaa-0000-0000-0000-000000000008', '6', 'حدثنا  عبد الرحمن بن مهدي  وأبو عامر  قالا حدثنا  زهير يعني ابن محمد  عن  عبد الله يعني ابن محمد بن عقيل  عن  معاذ بن رفاعة بن رافع الأنصاري  عن  أبيه  رفاعة بن رافع  قال سمعت  أبا بكر الصديق  رضي الله عنه  يقول على منبر رسول الله  صلى الله عليه وسلم  سمعت رسول الله  صلى الله عليه وسلم  يقول فبكى  أبو بكر  حين ذكر رسول الله  صلى الله عليه وسلم  ثم سري عنه ثم قال سمعت رسول الله  صلى الله عليه وسلم  يقول في هذا  القيظ  عام الأول  سلوا الله العفو والعافية واليقين في الآخرة والأولى', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a6a463d6-37bf-54bb-8877-8bc027688061', 'aaaaaaaa-0000-0000-0000-000000000008', '7', 'حدثنا  أبو كامل  قال حدثنا  حماد يعني ابن سلمة  عن  ابن أبي عتيق  عن  أبيه  عن  أبي بكر الصديق  رضي الله عنه  أن النبي  صلى الله عليه وسلم  قال  السواك  مطهرة  للفم مرضاة للرب', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a43f3ff9-0330-5439-8c47-e070aebc5276', 'aaaaaaaa-0000-0000-0000-000000000008', '8', 'حدثنا  هاشم بن القاسم  قال حدثنا  الليث  قال حدثني  يزيد بن أبي حبيب  عن  أبي الخير  عن  عبد الله بن عمرو  عن  أبي بكر الصديق  أنه قال لرسول الله  صلى الله عليه وسلم  علمني دعاء أدعو به في صلاتي قال قل  اللهم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم  و قال  يونس  كبيرا  حدثناه  حسن الأشيب  عن  ابن لهيعة  قال  قال  كبيرا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a732cc68-61fe-52e6-9636-70479aea7d7a', 'aaaaaaaa-0000-0000-0000-000000000008', '9', 'حدثنا  عبد الرزاق  قال حدثنا  معمر  عن  الزهري  عن  عروة  عن  عائشة  رضي الله عنها  أن  فاطمة  والعباس  أتيا  أبا بكر  رضي الله عنه  يلتمسان  ميراثهما من رسول الله  صلى الله عليه وسلم  وهما حينئذ يطلبان أرضه من  فدك  وسهمه  من  خيبر  فقال لهم  أبو بكر  إني سمعت رسول الله  صلى الله عليه وسلم  يقول  لا نورث ما تركنا  صدقة  إنما يأكل آل  محمد  في هذا المال  وإني والله لا أدع أمرا رأيت رسول الله  صلى الله عليه وسلم  يصنعه فيه إلا صنعته', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d195e997-7936-59fa-bd4f-0a86a41e1f9c', 'aaaaaaaa-0000-0000-0000-000000000008', '10', 'حدثنا  أبو عبد الرحمن المقرئ  قال حدثنا  حيوة بن شريح  قال سمعت  عبد الملك بن الحارث  يقول إن  أبا هريرة  قال سمعت  أبا بكر الصديق  رضي الله عنه  على هذا المنبر  يقول  سمعت رسول الله  صلى الله عليه وسلم  في هذا اليوم من عام الأول ثم  استعبر  أبو بكر  وبكى ثم قال سمعت رسول الله  صلى الله عليه وسلم  يقول  لم تؤتوا شيئا بعد كلمة الإخلاص مثل  العافية  فاسألوا الله  العافية', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2afb8208-24ff-55fc-be8f-a94ff9805491', 'aaaaaaaa-0000-0000-0000-000000000008', '11', 'حدثنا  عفان  قال حدثنا  همام  قال أخبرنا  ثابت  عن  أنس  أن  أبا بكر  حدثه قال  قلت للنبي  صلى الله عليه وسلم  وهو في الغار  وقال مرة ونحن في الغار  لو أن أحدهم نظر إلى قدميه لأبصرنا تحت قدميه قال فقال يا  أبا بكر  ما ظنك باثنين الله ثالثهما', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c5a19ee6-6e6a-5ce3-94d8-eee6d78537c2', 'aaaaaaaa-0000-0000-0000-000000000008', '12', 'حدثنا  روح  قال حدثنا  ابن أبي عروبة  عن  أبي التياح  عن  المغيرة بن سبيع  عن  عمرو بن حريث  عن  أبي بكر الصديق  قال  حدثنا رسول الله  صلى الله عليه وسلم  أن  الدجال  يخرج من أرض بالمشرق يقال لها  خراسان  يتبعه أقوام كأن وجوههم  المجان  المطرقة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('60347f8e-cd37-53f5-ad69-97c3444a2fd9', 'aaaaaaaa-0000-0000-0000-000000000008', '13', 'حدثنا  أبو سعيد  مولى  بني هاشم  قال حدثنا  صدقة بن موسى  صاحب الدقيق  عن  فرقد  عن  مرة بن شراحيل  عن  أبي بكر الصديق  رضي الله عنه  قال  قال رسول الله  صلى الله عليه وسلم  لا يدخل الجنة بخيل ولا خب ولا خائن ولا سيئ  الملكة  وأول من يقرع باب الجنة المملوكون إذا أحسنوا فيما بينهم وبين الله عز وجل وفيما بينهم وبين  مواليهم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d76563c9-abbe-53f3-b490-5871443859ec', 'aaaaaaaa-0000-0000-0000-000000000008', '14', 'حدثنا  عبد الله بن محمد بن أبي شيبة  قال  عبد الله  وسمعته  من  عبد الله بن أبي شيبة  قال حدثنا  محمد بن فضيل  عن  الوليد بن جميع  عن  أبي الطفيل  قال  لما قبض رسول الله  صلى الله عليه وسلم  أرسلت  فاطمة  إلى  أبي بكر  أنت ورثت رسول الله  صلى الله عليه وسلم  أم أهله قال فقال لا بل أهله قالت فأين  سهم  رسول الله  صلى الله عليه وسلم  قال فقال  أبو بكر  إني سمعت رسول الله  صلى الله عليه وسلم  يقول  إن الله عز وجل إذا أطعم نبيا  طعمة  ثم قبضه جعله للذي  يقوم  من بعده فرأيت أن أرده على المسلمين فقالت فأنت وما سمعت من رسول الله  صلى الله عليه وسلم  أعلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6cf64987-d7b7-5cec-b48b-90baf9d06a75', 'aaaaaaaa-0000-0000-0000-000000000008', '15', 'حدثنا  إبراهيم بن إسحاق الطالقاني  قال حدثني  النضر بن شميل المازني  قال حدثني  أبو نعامة  قال حدثني  أبو هنيدة البراء بن نوفل  عن  والان العدوي  عن  حذيفة  عن  أبي بكر الصديق  رضي الله عنه  قال  أصبح رسول الله  صلى الله عليه وسلم  ذات يوم فصلى  الغداة  ثم جلس حتى إذا كان من الضحى ضحك رسول الله  صلى الله عليه وسلم  ثم جلس مكانه حتى صلى الأولى والعصر والمغرب كل ذلك لا يتكلم حتى صلى العشاء الآخرة ثم قام إلى أهله فقال الناس  لأبي بكر  ألا تسأل رسول الله  صلى الله عليه وسلم  ما شأنه صنع اليوم شيئا لم يصنعه قط قال فسأله فقال نعم  عرض علي ما هو  كائن  من أمر الدنيا وأمر الآخرة فجمع الأولون والآخرون بصعيد واحد ففظع الناس بذلك حتى انطلقوا إلى  آدم  عليه السلام  والعرق يكاد يلجمهم فقالوا يا  آدم  أنت أبو البشر وأنت  اصطفاك  الله عز وجل اشفع لنا إلى ربك قال لقد لقيت مثل الذي لقيتم انطلقوا إلى أبيكم بعد أبيكم إلى  نوح  { إن الله اصطفى  آدم  ونوحا  وآل  إبراهيم  وآل  عمران  على العالمين } قال فينطلقون إلى  نوح  عليه السلام  فيقولون اشفع لنا إلى ربك فأنت اصطفاك الله واستجاب لك في دعائك ولم يدع على الأرض من الكافرين ديارا فيقول ليس  ذاكم عندي انطلقوا إلى  إبراهيم  عليه السلام  فإن الله عز وجل اتخذه  خليلا  فينطلقون إلى  إبراهيم  فيقول ليس  ذاكم عندي ولكن انطلقوا إلى  موسى  عليه السلام  فإن الله عز وجل كلمه تكليما فيقول  موسى  عليه السلام  ليس  ذاكم عندي ولكن انطلقوا إلى  عيسى ابن مريم  فإنه يبرئ  الأكمه  والأبرص  ويحيي الموتى فيقول  عيسى  ليس  ذاكم عندي ولكن انطلقوا إلى سيد ولد  آدم  فإنه أول من  تنشق  عنه الأرض يوم القيامة انطلقوا إلى  محمد  صلى الله عليه وسلم  فيشفع لكم إلى ربكم عز وجل قال فينطلق فيأتي  جبريل  عليه السلام  ربه فيقول الله عز وجل ائذن له وبشره بالجنة قال فينطلق به  جبريل  فيخر ساجدا قدر جمعة ويقول الله عز وجل ارفع رأسك يا  محمد  وقل يسمع واشفع تشفع قال فيرفع رأسه فإذا نظر إلى ربه عز وجل  خر  ساجدا قدر جمعة أخرى فيقول الله عز وجل ارفع رأسك وقل يسمع واشفع تشفع قال فيذهب ليقع ساجدا فيأخذ  جبريل  عليه السلام  بضبعيه فيفتح الله عز وجل عليه من الدعاء شيئا لم يفتحه على بشر قط فيقول أي رب خلقتني سيد ولد  آدم  ولا فخر وأول من  تنشق  عنه الأرض يوم القيامة ولا فخر حتى إنه ليرد علي الحوض أكثر مما بين  صنعاء  وأيلة  ثم يقال ادعوا الصديقين فيشفعون ثم يقال ادعوا الأنبياء قال فيجيء النبي ومعه  العصابة  والنبي ومعه الخمسة والستة والنبي وليس معه أحد ثم يقال ادعوا الشهداء فيشفعون لمن أرادوا وقال فإذا فعلت الشهداء ذلك قال يقول الله عز وجل أنا أرحم الراحمين أدخلوا جنتي من كان لا يشرك بي شيئا قال فيدخلون الجنة قال ثم يقول الله عز وجل انظروا في النار هل تلقون من أحد عمل خيرا قط قال فيجدون في النار رجلا فيقول له هل عملت خيرا قط فيقول لا غير أني كنت أسامح الناس في البيع والشراء فيقول الله عز وجل أسمحوا لعبدي كإسماحه إلى عبيدي ثم يخرجون من النار رجلا فيقول له هل عملت خيرا قط فيقول لا غير أني قد أمرت ولدي إذا مت فأحرقوني بالنار ثم اطحنوني حتى إذا كنت مثل الكحل فاذهبوا بي إلى البحر  فاذروني  في الريح فوالله لا يقدر علي رب العالمين أبدا فقال الله عز وجل لم فعلت ذلك قال من مخافتك قال فيقول الله عز وجل انظر إلى ملك أعظم ملك فإن لك مثله وعشرة أمثاله قال فيقول لم تسخر بي وأنت الملك قال وذاك الذي ضحكت منه من الضحى', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('19a775fa-03a5-5bcb-b655-53e432969e6a', 'aaaaaaaa-0000-0000-0000-000000000008', '16', 'حدثنا  هاشم بن القاسم  قال حدثنا  زهير يعني ابن معاوية  قال حدثنا  إسماعيل بن أبي خالد  قال حدثنا  قيس  قال  قام  أبو بكر  رضي الله عنه  فحمد الله عز وجل وأثنى عليه فقال يا أيها الناس إنكم تقرءون هذه الآية  { يا أيها الذين آمنوا عليكم أنفسكم لا يضركم من ضل إذا اهتديتم } إلى آخر الآية وإنكم تضعونها على غير موضعها وإني سمعت رسول الله  صلى الله عليه وسلم  يقول  إن الناس إذا رأوا المنكر ولا يغيروه  أوشك  الله أن يعمهم بعقابه  قال  وسمعت  أبا بكر  رضي الله عنه  يقول  يا أيها الناس إياكم والكذب فإن الكذب مجانب للإيمان', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1854efc3-1093-5403-ae44-01dd8ee95601', 'aaaaaaaa-0000-0000-0000-000000000008', '17', 'حدثنا  هاشم  قال حدثنا  شعبة  قال أخبرني  يزيد بن خمير  قال سمعت  سليم بن عامر  رجلا من  حمير  يحدث عن  أوسط بن إسماعيل بن أوسط البجلي  يحدث عن  أبي بكر  أنه سمعه حين توفي رسول الله  صلى الله عليه وسلم  قال قام رسول الله  صلى الله عليه وسلم  عام الأول مقامي هذا ثم بكى ثم قال  عليكم بالصدق فإنه مع البر وهما في الجنة وإياكم والكذب فإنه مع الفجور وهما في النار وسلوا الله المعافاة فإنه لم يؤت رجل بعد اليقين شيئا خيرا من المعافاة ثم قال لا تقاطعوا ولا تدابروا ولا تباغضوا ولا تحاسدوا وكونوا عباد الله إخوانا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('78000fbb-9219-53aa-a249-ba709a8b3c58', 'aaaaaaaa-0000-0000-0000-000000000008', '18', 'حدثنا  عفان  قال حدثنا  أبو عوانة  عن  داود بن عبد الله الأودي  عن  حميد بن عبد الرحمن  قال  توفي رسول الله  صلى الله عليه وسلم  وأبو بكر  في طائفة من  المدينة  قال فجاء فكشف عن وجهه فقبله وقال فداك أبي وأمي ما أطيبك حيا وميتا مات  محمد  صلى الله عليه وسلم  ورب  الكعبة  فذكر الحديث  قال فانطلق  أبو بكر  وعمر  يتقاودان حتى أتوهم فتكلم  أبو بكر  ولم يترك شيئا أنزل في  الأنصار  ولا ذكره رسول الله  صلى الله عليه وسلم  من شأنهم إلا وذكره وقال ولقد علمتم أن رسول الله  صلى الله عليه وسلم  قال  لو سلك الناس واديا وسلكت  الأنصار  واديا سلكت وادي  الأنصار  ولقد علمت يا  سعد  أن رسول الله  صلى الله عليه وسلم  قال وأنت قاعد  قريش  ولاة هذا الأمر فبر الناس تبع لبرهم وفاجرهم تبع لفاجرهم قال فقال له  سعد  صدقت نحن الوزراء وأنتم الأمراء', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1b098eb3-8ef1-5678-b54e-8b06fd308f46', 'aaaaaaaa-0000-0000-0000-000000000008', '19', 'حدثنا  علي بن عياش  قال حدثنا  العطاف بن خالد  قال حدثني  رجل  من أهل  البصرة  عن  طلحة بن عبد الله بن عبد الرحمن بن أبي بكر الصديق  قال سمعت  أبي  يذكر أن  أباه  سمع  أبا بكر  وهو  يقول  قلت لرسول الله  صلى الله عليه وسلم  يا رسول الله العمل على ما فرغ منه أو على أمر  مؤتنف  قال بل على أمر قد فرغ منه قال قلت ففيم العمل يا رسول الله قال  كل ميسر لما خلق له', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fe64e9ca-7cec-51cb-878c-84600ff01528', 'aaaaaaaa-0000-0000-0000-000000000008', '20', 'حدثنا  أبو اليمان  قال أخبرنا  شعيب  عن  الزهري  قال أخبرني  رجل  من  الأنصار  من أهل الفقه  أنه سمع  عثمان بن عفان  رضي الله عنه  يحدث  أن رجالا من  أصحاب النبي  صلى الله عليه وسلم  حين توفي النبي  صلى الله عليه وسلم  حزنوا عليه حتى كاد بعضهم يوسوس قال  عثمان  وكنت منهم فبينا أنا جالس في ظل  أطم  من  الآطام  مر علي  عمر  رضي الله عنه  فسلم علي فلم أشعر أنه مر ولا سلم فانطلق  عمر  حتى دخل على  أبي بكر  رضي الله عنه  فقال له ما يعجبك أني مررت على  عثمان  فسلمت عليه فلم يرد علي السلام وأقبل هو  وأبو بكر  في ولاية  أبي بكر  رضي الله عنه  حتى سلما علي جميعا ثم  قال  أبو بكر  جاءني أخوك  عمر  فذكر أنه مر عليك فسلم فلم ترد عليه السلام فما الذي حملك على ذلك قال قلت ما فعلت فقال  عمر  بلى والله لقد فعلت ولكنها عبيتكم يا  بني أمية  قال قلت والله ما شعرت أنك مررت ولا سلمت قال  أبو بكر  صدق  عثمان  وقد شغلك عن ذلك أمر فقلت أجل قال ما هو فقال  عثمان  رضي الله عنه  توفى الله عز وجل نبيه  صلى الله عليه وسلم  قبل أن نسأله عن نجاة هذا الأمر قال  أبو بكر  قد سألته عن ذلك قال فقمت إليه فقلت له بأبي أنت وأمي أنت أحق بها قال  أبو بكر  قلت يا رسول الله ما نجاة هذا الأمر فقال رسول الله  صلى الله عليه وسلم  من قبل مني الكلمة التي عرضت على عمي فردها علي فهي له نجاة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9c74c3df-2622-5ff1-a559-3180010d2f71', 'aaaaaaaa-0000-0000-0000-000000000008', '21', 'حدثنا  يزيد بن عبد ربه  قال حدثنا  بقية بن الوليد  قال حدثني  شيخ  من  قريش  عن  رجاء بن حيوة  عن  جنادة بن أبي أمية  عن  يزيد بن أبي سفيان  قال  قال  أبو بكر  رضي الله عنه  حين بعثني إلى  الشام  يا  يزيد  إن لك قرابة عسيت أن تؤثرهم بالإمارة وذلك أكبر ما أخاف عليك فإن رسول الله  صلى الله عليه وسلم  قال  من ولي من أمر المسلمين شيئا فأمر عليهم أحدا  محاباة  فعليه لعنة الله لا يقبل الله منه  صرفا  ولا عدلا حتى يدخله جهنم ومن أعطى أحدا  حمى  الله فقد انتهك في  حمى  الله شيئا بغير حقه فعليه لعنة الله  أو قال تبرأت منه ذمة الله  عز وجل', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0ad46ae6-fa72-5869-9aec-c9b098b97a65', 'aaaaaaaa-0000-0000-0000-000000000008', '22', 'حدثنا  هاشم بن القاسم  قال حدثنا  المسعودي  قال حدثني  بكير بن الأخنس  عن  رجل  عن  أبي بكر الصديق  قال  قال رسول الله  صلى الله عليه وسلم  أعطيت سبعين ألفا يدخلون الجنة بغير حساب وجوههم كالقمر ليلة البدر وقلوبهم على قلب رجل واحد فاستزدت ربي عز وجل فزادني مع كل واحد سبعين ألفا  قال  أبو بكر  رضي الله عنه  فرأيت أن ذلك آت على أهل القرى ومصيب من حافات البوادي', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8c7900cd-3d14-5e46-a6da-9044f462fb2b', 'aaaaaaaa-0000-0000-0000-000000000008', '23', 'حدثنا  عبد الوهاب بن عطاء  عن  زياد الجصاص  عن  علي بن زيد  عن  مجاهد  عن  ابن عمر  قال سمعت  أبا بكر  يقول  قال رسول الله  صلى الله عليه وسلم  من يعمل سوءا يجز به في الدنيا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9bdf6b28-297e-53ee-aea4-3fc40961370d', 'aaaaaaaa-0000-0000-0000-000000000008', '24', 'حدثنا  يعقوب  حدثنا  أبي  عن  صالح  قال قال  ابن شهاب  أخبرني  رجل  من  الأنصار  غير متهم  أنه سمع  عثمان بن عفان  يحدث  أن رجالا من  أصحاب النبي  صلى الله عليه وسلم  حين توفي رسول الله  صلى الله عليه وسلم  حزنوا عليه حتى كاد بعضهم أن يوسوس  قال  عثمان  فكنت منهم فذكر معنى حديث  أبي اليمان  عن  شعيب', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1409e5aa-7449-5dd6-971e-9e4946f498e3', 'aaaaaaaa-0000-0000-0000-000000000008', '25', 'حدثنا  يعقوب  قال حدثنا  أبي  عن  صالح  قال  ابن شهاب  أخبرني  عروة بن الزبير  أن  عائشة  رضي الله عنها  زوج النبي  صلى الله عليه وسلم  أخبرته أن  فاطمة بنت رسول الله  صلى الله عليه وسلم  سألت  أبا بكر  رضي الله عنه  بعد وفاة رسول الله  صلى الله عليه وسلم  أن يقسم لها ميراثها مما ترك رسول الله  صلى الله عليه وسلم  مما  أفاء  الله عليه فقال لها  أبو بكر  رضي الله عنه  إن رسول الله  صلى الله عليه وسلم  قال  لا نورث ما تركنا  صدقة  فغضبت  فاطمة  عليها السلام  فهجرت  أبا بكر  رضي الله عنه  فلم تزل مهاجرته حتى توفيت قال وعاشت بعد وفاة رسول الله  صلى الله عليه وسلم  ستة أشهر قال وكانت  فاطمة  رضي الله عنها  تسأل  أبا بكر  نصيبها مما ترك رسول الله  صلى الله عليه وسلم  من  خيبر  وفدك  وصدقته  بالمدينة  فأبى  أبو بكر  عليها ذلك وقال لست تاركا شيئا كان رسول الله  صلى الله عليه وسلم  يعمل به إلا عملت به وإني أخشى إن تركت شيئا من أمره أن أزيغ فأما صدقته  بالمدينة  فدفعها  عمر  إلى  علي  وعباس  فغلبه عليها  علي  وأما  خيبر  وفدك  فأمسكهما  عمر  رضي الله عنه  وقال هما  صدقة  رسول الله  صلى الله عليه وسلم  كانتا لحقوقه التي تعروه  ونوائبه  وأمرهما إلى من  ولي  الأمر قال فهما على ذلك اليوم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d71bde33-6500-57aa-a496-db0225b89eba', 'aaaaaaaa-0000-0000-0000-000000000008', '26', 'حدثنا  حسن بن موسى  وعفان  قالا حدثنا  حماد بن سلمة  عن  علي بن زيد  عن  القاسم بن محمد  عن  عائشة  رضي الله عنها  أنها تمثلت بهذا البيت  وأبو بكر  رضي الله عنه  يقضي  وأبيض يستسقى الغمام بوجهه  ربيع اليتامى  عصمة  للأرامل  فقال  أبو بكر  رضي الله عنه  ذاك والله رسول الله  صلى الله عليه وسلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6c9d3afd-c429-5a15-9612-2567e255d0c9', 'aaaaaaaa-0000-0000-0000-000000000008', '27', 'حدثنا  عبد الرزاق  قال أخبرني  ابن جريج  قال أخبرني  أبي  أن  أصحاب النبي  صلى الله عليه وسلم  لم يدروا أين يقبرون النبي  صلى الله عليه وسلم  حتى قال  أبو بكر  رضي الله عنه  سمعت رسول الله  صلى الله عليه وسلم  يقول  لن  يقبر  نبي إلا حيث يموت فأخروا فراشه وحفروا له تحت فراشه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a3461e88-1147-5b82-a908-7e89e21f9212', 'aaaaaaaa-0000-0000-0000-000000000008', '28', 'حدثنا  حجاج  قال حدثنا  ليث  قال حدثني  يزيد بن أبي حبيب  عن  أبي الخير  عن  عبد الله بن عمرو بن العاص  عن  أبي بكر الصديق  رضي الله عنه  أنه قال لرسول الله  صلى الله عليه وسلم  علمني دعاء أدعو به في صلاتي قال قل  اللهم إني ظلمت نفسي ظلما كثيرا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d4adf589-faff-5c34-bb94-6d4793e59c96', 'aaaaaaaa-0000-0000-0000-000000000008', '29', 'حدثنا  حماد بن أسامة  قال أخبرنا  إسماعيل  عن  قيس  قال  قام  أبو بكر  فحمد الله وأثنى عليه ثم قال يا أيها الناس إنكم تقرءون هذه الآية  { يا أيها الذين آمنوا عليكم أنفسكم } حتى أتى على آخر الآية ألا  وإن الناس إذا رأوا الظالم لم يأخذوا على يديه  أوشك  الله أن يعمهم بعقابه ألا وإني سمعت رسول الله  صلى الله عليه وسلم  يقول إن الناس  وقال مرة أخرى وإنا سمعنا رسول الله  صلى الله عليه وسلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da576910-2207-5a92-ab18-7c5c893b8606', 'aaaaaaaa-0000-0000-0000-000000000008', '30', 'حدثنا  يزيد بن هارون  قال أخبرنا  إسماعيل بن أبي خالد  عن  قيس بن أبي حازم  عن  أبي بكر الصديق  رضي الله عنه  قال  أيها الناس إنكم تقرءون هذه الآية  { يا أيها الذين آمنوا عليكم أنفسكم لا يضركم من ضل إذا اهتديتم } وإني سمعت رسول الله  صلى الله عليه وسلم  يقول  إن الناس إذا رأوا الظالم فلم يأخذوا على يديه أوشك أن يعمهم الله بعقابه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b0490992-b4c2-5bee-820d-67653a19059a', 'aaaaaaaa-0000-0000-0000-000000000008', '31', 'حدثنا  يزيد  قال أخبرنا  همام  عن  فرقد السبخي  وعفان  قالا حدثنا  مرة الطيب  عن  أبي بكر الصديق  رضي الله عنه  عن النبي  صلى الله عليه وسلم  قال  لا يدخل الجنة سيئ  الملكة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('340fc78c-30f4-539f-aa85-c4f85ad75293', 'aaaaaaaa-0000-0000-0000-000000000008', '32', 'حدثنا  يزيد بن هارون  أخبرنا  صدقة بن موسى  عن  فرقد السبخي  عن  مرة الطيب  عن  أبي بكر الصديق  رضي الله عنه  عن النبي  صلى الله عليه وسلم  قال  لا يدخل الجنة  خب  ولا بخيل ولا  منان  ولا سيئ  الملكة  وأول من يدخل الجنة المملوك إذا أطاع الله وأطاع سيده', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('056305c4-12c7-59bf-b6bf-61907e18f51f', 'aaaaaaaa-0000-0000-0000-000000000008', '33', 'حدثنا  روح  قال حدثنا  سعيد بن أبي عروبة  عن  أبي التياح  عن  المغيرة بن سبيع  عن  عمرو بن حريث  أن  أبا بكر الصديق  رضي الله عنه  أفاق من مرضة له فخرج إلى الناس فاعتذر بشيء وقال ما أردنا إلا الخير ثم قال حدثنا رسول الله  صلى الله عليه وسلم  أن  الدجال  يخرج من أرض بالمشرق يقال لها  خراسان  يتبعه أقوام كأن وجوههم  المجان  المطرقة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('268f2db4-cfa8-5445-9060-19b46ffe1d59', 'aaaaaaaa-0000-0000-0000-000000000008', '34', 'حدثنا  روح  قال حدثنا  شعبة  عن  يزيد بن خمير  قال سمعت  سليم بن عامر  رجلا من أهل  حمص  وكان قد أدرك  أصحاب رسول الله  صلى الله عليه وسلم  وقال مرة  قال سمعت  أوسط البجلي  عن  أبي بكر الصديق  رضي الله عنه  قال سمعته  يخطب الناس  وقال مرة حين استخلف  فقال  إن رسول الله  صلى الله عليه وسلم  قام عام الأول مقامي هذا وبكى  أبو بكر  رضي الله عنه  فقال  أسأل الله العفو والعافية فإن الناس لم يعطوا بعد اليقين شيئا خيرا من العافية وعليكم بالصدق فإنه في الجنة وإياكم والكذب فإنه مع الفجور وهما في النار ولا تقاطعوا ولا تباغضوا ولا تحاسدوا ولا تدابروا وكونوا إخوانا كما أمركم الله عز وجل', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7ca05cab-ccc3-5be7-a836-035d550e472c', 'aaaaaaaa-0000-0000-0000-000000000008', '35', 'حدثنا  يحيى بن آدم  قال حدثنا  أبو بكر يعني ابن عياش  عن  عاصم  عن  زر  عن  عبد الله  أن  أبا بكر  وعمر  رضي الله عنهما  بشراه أن رسول الله  صلى الله عليه وسلم  قال  من سره أن يقرأ القرآن غضا كما أنزل فليقرأه على قراءة  ابن أم عبد  قال  حدثنا  يحيى بن آدم  حدثنا  أبو بكر  ويزيد بن عبد العزيز  عن  الأعمش  عن  إبراهيم  عن  علقمة  عن  عمر بن الخطاب  رضي الله عنه  عن النبي  صلى الله عليه وسلم  مثله قال غضا  أو رطبا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('63337518-3a97-5bbc-9ec5-a349662133e7', 'aaaaaaaa-0000-0000-0000-000000000008', '36', 'حدثنا  أبو سعيد  مولى  بني هاشم  حدثنا  عبد العزيز بن محمد  وسعيد بن سلمة بن أبي الحسام  عن  عمرو بن أبي عمرو  عن  أبي الحويرث  عن  محمد بن جبير بن مطعم  أن  عثمان  رضي الله عنه  قال  تمنيت أن أكون سألت رسول الله  صلى الله عليه وسلم  ماذا  ينجينا مما  يلقي الشيطان في أنفسنا  فقال  أبو بكر  رضي الله عنه  قد سألته عن ذلك فقال  ينجيكم من ذلك أن تقولوا ما أمرت عمي أن يقوله', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da98b2f7-927d-5749-a5e7-c727bc913bf1', 'aaaaaaaa-0000-0000-0000-000000000008', '37', 'حدثنا  إسماعيل بن إبراهيم  عن  يونس  عن  الحسن  أن  أبا بكر  رضي الله عنه  خطب الناس فقال قال رسول الله  صلى الله عليه وسلم  يا أيها الناس  إن الناس لم يعطوا في الدنيا خيرا من اليقين والمعافاة فسلوهما الله عز وجل', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('04876e60-d9a9-58a9-b7b2-d461e4ded7d9', 'aaaaaaaa-0000-0000-0000-000000000008', '38', 'حدثنا  يعقوب بن إبراهيم  حدثنا  أبي  عن  ابن إسحاق  قال وحدثني  حسين بن عبد الله  عن  عكرمة  مولى  ابن عباس  عن  ابن عباس  قال  لما أرادوا أن يحفروا لرسول الله  صلى الله عليه وسلم  وكان  أبو عبيدة بن الجراح  يضرح كحفر أهل  مكة  وكان  أبو طلحة زيد بن سهل  يحفر لأهل  المدينة  فكان  يلحد  فدعا  العباس  رجلين فقال لأحدهما اذهب إلى  أبي عبيدة  وللآخر اذهب إلى  أبي طلحة  اللهم خر لرسولك قال فوجد صاحب  أبي طلحة  أبا طلحة  فجاء به فلحد لرسول الله  صلى الله عليه وسلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dba96951-e2ae-5505-a2be-c0daccf42de1', 'aaaaaaaa-0000-0000-0000-000000000008', '39', 'حدثنا  محمد بن عبد الله بن الزبير  حدثنا  عمر بن سعيد  عن  ابن أبي مليكة  أخبرني  عقبة بن الحارث  قال  خرجت مع  أبي بكر الصديق  رضي الله عنه  من صلاة العصر بعد وفاة النبي  صلى الله عليه وسلم  بليال  وعلي  عليه السلام  يمشي إلى جنبه فمر  بحسن بن علي  يلعب مع غلمان فاحتمله على رقبته وهو يقول  وا بأبي شبه النبي  ليس شبيها  بعلي  قال  وعلي  يضحك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b7f805bc-6d4e-564b-9d9d-d054a96a6aa5', 'aaaaaaaa-0000-0000-0000-000000000008', '40', 'حدثنا  أسود بن عامر  حدثنا  إسرائيل  عن  جابر  عن  عامر  عن  عبد الرحمن بن أبزى  عن  أبي بكر  قال  كنت عند النبي  صلى الله عليه وسلم  جالسا فجاء  ماعز بن مالك  فاعترف عنده مرة فرده ثم جاءه فاعترف عنده الثانية فرده ثم جاءه فاعترف الثالثة فرده فقلت له إنك إن اعترفت الرابعة  رجمك  قال فاعترف الرابعة فحبسه ثم سأل عنه فقالوا ما نعلم إلا خيرا قال  فأمر  برجمه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9aa8192c-d271-5c1e-8a97-71093be00b28', 'aaaaaaaa-0000-0000-0000-000000000008', '41', 'حدثنا  علي بن عياش  حدثنا  الوليد بن مسلم  قال أخبرني  يزيد بن سعيد بن ذي عصوان العنسي  عن  عبد الملك بن عمير اللخمي  عن  رافع الطائي  رفيق  أبي بكر  في  غزوة السلاسل  قال  وسألته عما قيل من بيعتهم فقال وهو يحدثه عما تكلمت به  الأنصار  وما كلمهم به وما كلم به  عمر بن الخطاب  الأنصار  وما ذكرهم به من إمامتي إياهم بأمر رسول الله  صلى الله عليه وسلم  في مرضه  فبايعوني لذلك وقبلتها منهم وتخوفت أن تكون  فتنة  تكون بعدها ردة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c64293aa-8397-5b92-a9e0-8901a7f00641', 'aaaaaaaa-0000-0000-0000-000000000008', '42', 'حدثنا  علي بن عياش  حدثنا  الوليد بن مسلم  حدثني  وحشي بن حرب  عن  أبيه  عن  جده وحشي بن حرب  أن  أبا بكر  رضي الله عنه  عقد  لخالد بن الوليد  على قتال أهل الردة وقال إني سمعت رسول الله  صلى الله عليه وسلم  يقول  نعم عبد الله وأخو العشيرة  خالد بن الوليد  وسيف من سيوف الله سله الله عز وجل على الكفار والمنافقين', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1557d214-ac9c-5b23-8d0b-9649c22021be', 'aaaaaaaa-0000-0000-0000-000000000008', '43', 'حدثنا  عبد الرحمن بن مهدي  حدثنا  معاوية يعني ابن صالح  عن  سليم بن عامر الكلاعي  عن  أوسط بن عمرو  قال  قدمت  المدينة  بعد وفاة رسول الله  صلى الله عليه وسلم  بسنة فألفيت  أبا بكر  يخطب الناس فقال قام فينا رسول الله  صلى الله عليه وسلم  عام الأول فخنقته  العبرة  ثلاث مرار ثم قال يا أيها الناس  سلوا الله المعافاة فإنه لم يؤت أحد مثل يقين بعد معافاة ولا أشد من ريبة بعد كفر وعليكم بالصدق فإنه  يهدي  إلى البر وهما في الجنة وإياكم والكذب فإنه  يهدي  إلى الفجور وهما في النار', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92df77ea-a1f0-5752-8630-bd3a0841371a', 'aaaaaaaa-0000-0000-0000-000000000008', '44', 'حدثنا  محمد بن ميسر أبو سعد الصاغاني  المكفوف  حدثنا  هشام بن عروة  عن  أبيه  عن  عائشة  رضي الله عنها  قالت  إن  أبا بكر  رضي الله عنه  لما حضرته الوفاة قال أي يوم هذا قالوا يوم  الاثنين قال  فإن مت من ليلتي فلا تنتظروا بي الغد فإن أحب الأيام والليالي إلي أقربها من رسول الله  صلى الله عليه وسلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('70991783-bbcd-5c68-aac6-ed2d7156f5ee', 'aaaaaaaa-0000-0000-0000-000000000008', '45', 'حدثنا  وكيع  عن  سفيان  حدثنا  عمرو بن مرة  عن  أبي عبيدة  قال  قام  أبو بكر  رضي الله عنه  بعد وفاة رسول الله  صلى الله عليه وسلم  بعام فقال قام رسول الله  صلى الله عليه وسلم  مقامي عام الأول فقال  سلوا الله العافية فإنه لم يعط عبد شيئا  أفضل  من العافية وعليكم بالصدق  والبر  فإنهما في الجنة وإياكم والكذب والفجور فإنهما في النار', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4081b811-efdc-5689-af13-447f7cd6b560', 'aaaaaaaa-0000-0000-0000-000000000008', '46', 'حدثنا  عبد الرحمن بن مهدي  حدثنا  شعبة  عن  عثمان بن المغيرة  قال سمعت  علي بن ربيعة  من  بني أسد  يحدث عن  أسماء  أو  ابن أسماء  من  بني فزارة  قال قال  علي  رضي الله عنه  كنت إذا سمعت من رسول الله  صلى الله عليه وسلم  شيئا نفعني الله بما شاء أن ينفعني منه  وحدثني  أبو بكر  وصدق  أبو بكر  قال قال رسول الله  صلى الله عليه وسلم  ما من مسلم يذنب ذنبا ثم يتوضأ فيصلي ركعتين ثم يستغفر الله تعالى لذلك الذنب إلا غفر له وقرأ هاتين الآيتين  { ومن يعمل سوءا أو يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما } { والذين إذا فعلوا  فاحشة  أو ظلموا أنفسهم } الآية  حدثنا  محمد بن جعفر  حدثنا  شعبة  قال سمعت  عثمان  من آل  أبي عقيل الثقفي  إلا أنه قال قال  شعبة  وقرأ إحدى هاتين الآيتين  { من يعمل سوءا يجز به } { والذين إذا فعلوا فاحشة }', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e5a10d98-8c39-5a9c-b158-2bec4bca2011', 'aaaaaaaa-0000-0000-0000-000000000008', '47', 'حدثنا  بهز بن أسد  حدثنا  سليم بن حيان  قال سمعت  قتادة  يحدث عن  حميد بن عبد الرحمن  أن  عمر  قال إن  أبا بكر  رضي الله عنه  خطبنا  فقال  إن رسول الله  صلى الله عليه وسلم  قام فينا عام أول فقال  ألا إنه لم يقسم بين الناس شيء أفضل من المعافاة بعد اليقين ألا إن الصدق والبر في الجنة ألا إن الكذب والفجور في النار', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('63350cd2-b08d-5e83-aed8-571babb1aa34', 'aaaaaaaa-0000-0000-0000-000000000008', '48', 'حدثنا  محمد بن جعفر  حدثنا  شعبة  قال سمعت  أبا إسحاق  يقول سمعت  البراء  قال  لما أقبل رسول الله  صلى الله عليه وسلم  من  مكة  إلى  المدينة  عطش رسول الله  صلى الله عليه وسلم  فمروا براعي غنم  قال  أبو بكر الصديق  رضي الله عنه  فأخذت قدحا فحلبت فيه لرسول الله  صلى الله عليه وسلم  كثبة  من لبن فأتيته به  فشرب حتى رضيت', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6f1727fd-6ca9-5c90-927d-41563935b2ba', 'aaaaaaaa-0000-0000-0000-000000000008', '49', 'حدثنا  بهز  حدثنا  شعبة  حدثنا  يعلى بن عطاء  قال سمعت  عمرو بن عاصم  يقول سمعت  أبا هريرة  يقول  قال  أبو بكر  رضي الله عنه  يا رسول الله علمني شيئا أقوله إذا أصبحت وإذا أمسيت وإذا أخذت  مضجعي  قال قل  اللهم فاطر السموات والأرض عالم الغيب والشهادة  أو قال اللهم عالم الغيب والشهادة  فاطر  السموات والأرض  رب كل شيء ومليكه أشهد أن لا إله إلا أنت أعوذ بك من شر نفسي وشر الشيطان  وشركه  حدثنا  عفان  حدثنا  شعبة  عن  يعلى بن عطاء  قال سمعت  عمرو بن عاصم بن عبد الله  فذكر معناه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad41f01e-4420-5d98-8b41-1595a0425d23', 'aaaaaaaa-0000-0000-0000-000000000008', '50', 'حدثنا  محمد بن جعفر  حدثنا  شعبة  عن  إسماعيل  قال سمعت  قيس بن أبي حازم  يحدث  عن  أبي بكر الصديق  رضي الله عنه  أنه خطب فقال يا أيها الناس إنكم تقرءون هذه الآية وتضعونها على غير ما وضعها الله  { يا أيها الذين آمنوا عليكم أنفسكم لا يضركم من ضل إذا اهتديتم } سمعت رسول الله  صلى الله عليه وسلم  يقول  إن الناس إذا رأوا المنكر بينهم فلم ينكروه يوشك أن يعمهم الله بعقابه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a859d39f-6376-5aac-a968-a32b871bcf9a', 'aaaaaaaa-0000-0000-0000-000000000008', '51', 'حدثنا  محمد بن جعفر  حدثنا  شعبة  عن  توبة العنبري  قال سمعت  أبا سوار القاضي  يقول عن  أبي برزة الأسلمي  قال  أغلظ رجل  لأبي بكر الصديق  رضي الله عنه  قال فقال  أبو برزة  ألا أضرب عنقه قال فانتهره وقال  ما هي لأحد بعد رسول الله  صلى الله عليه وسلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fafe8218-9123-576a-ae31-b8ab4182df8a', 'aaaaaaaa-0000-0000-0000-000000000008', '52', 'حدثنا  حجاج بن محمد  حدثنا  ليث  حدثني  عقيل  عن  ابن شهاب  عن  عروة بن الزبير  عن  عائشة  رضي الله عنها  زوج النبي  صلى الله عليه وسلم  أنها أخبرته  أن  فاطمة بنت رسول الله  صلى الله عليه وسلم  أرسلت إلى  أبي بكر الصديق  رضي الله عنه  تسأله ميراثها من رسول الله  صلى الله عليه وسلم  مما  أفاء  الله عليه  بالمدينة  وفدك  وما بقي من خمس  خيبر  فقال  أبو بكر  رضي الله عنه  إن رسول الله  صلى الله عليه وسلم  قال  لا نورث ما تركنا  صدقة  إنما يأكل آل  محمد  في هذا المال وإني والله لا أغير شيئا من  صدقة  رسول الله  صلى الله عليه وسلم  عن حالها التي كانت عليها في  عهد  رسول الله  صلى الله عليه وسلم  ولأعملن فيها بما عمل به رسول الله  صلى الله عليه وسلم  فأبى  أبو بكر  أن يدفع إلى  فاطمة  منها شيئا  فوجدت  فاطمة  على  أبي بكر  في ذلك فقال  أبو بكر  والذي نفسي بيده لقرابة رسول الله  صلى الله عليه وسلم  أحب إلي أن أصل من قرابتي وأما الذي شجر بيني وبينكم من هذه الأموال فإني  لم آل  فيها عن الحق ولم أترك أمرا رأيت رسول الله  صلى الله عليه وسلم  يصنعه فيها إلا صنعته', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5fabacb8-ac02-531d-a123-260f7737bdda', 'aaaaaaaa-0000-0000-0000-000000000008', '53', 'حدثنا  أبو كامل  حدثنا  أبو عوانة  حدثنا  عثمان بن أبي زرعة  عن  علي بن ربيعة  عن  أسماء بن الحكم الفزاري  قال سمعت  عليا  كرم الله وجهه  قال  كنت إذا سمعت من رسول الله  صلى الله عليه وسلم  حديثا نفعني الله به بما شاء أن ينفعني منه وإذا حدثني غيره استحلفته فإذا حلف لي صدقته  وحدثني  أبو بكر  وصدق  أبو بكر  قال قال رسول الله  صلى الله عليه وسلم  ما من عبد مؤمن يذنب ذنبا فيتوضأ فيحسن الطهور ثم  يصلي ركعتين فيستغفر الله تعالى إلا غفر الله له ثم تلا  { والذين إذا فعلوا  فاحشة  أو ظلموا أنفسهم }', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e8473548-9ab1-5fc0-b7f2-64a22fd738d6', 'aaaaaaaa-0000-0000-0000-000000000008', '54', 'حدثنا  أبو كامل  حدثنا  إبراهيم بن سعد  حدثنا  ابن شهاب  عن  عبيد بن السباق  عن  زيد بن ثابت  قال  أرسل إلي  أبو بكر  رضي الله عنه  مقتل أهل  اليمامة  فقال  أبو بكر  يا  زيد بن ثابت  أنت  غلام شاب  عاقل  لا نتهمك قد  كنت تكتب الوحي لرسول الله  صلى الله عليه وسلم  فتتبع القرآن فاجمعه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3c890292-6f60-51ba-bb16-34dc8230b95d', 'aaaaaaaa-0000-0000-0000-000000000008', '55', 'حدثنا  عبد الرزاق  حدثنا  معمر  عن  الزهري  عن  عروة  عن  عائشة  رضي الله عنها  أن  فاطمة  والعباس  أتيا  أبا بكر  يلتمسان  ميراثهما من رسول الله  صلى الله عليه وسلم  وهما حينئذ يطلبان أرضه من  فدك  وسهمه  من  خيبر  فقال  لهما  أبو بكر  رضي الله عنه  إني سمعت رسول الله  صلى الله عليه وسلم  يقول  لا نورث ما تركنا  صدقة  وإنما يأكل آل  محمد  صلى الله عليه وسلم  في هذا المال وإني والله لا أدع أمرا رأيت رسول الله  صلى الله عليه وسلم  يصنعه فيه إلا صنعته', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c1eeab0f-bf2e-5402-8ac2-97f4c2370bba', 'aaaaaaaa-0000-0000-0000-000000000008', '56', 'حدثنا  موسى بن داود  حدثنا  نافع يعني ابن عمر  عن  ابن أبي مليكة  قال  قيل  لأبي بكر  رضي الله عنه  يا خليفة الله فقال  أنا خليفة رسول الله  صلى الله عليه وسلم  وأنا راض به وأنا راض به وأنا راض', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6cf9681f-757d-5f0e-9e0f-5b2f674ac63d', 'aaaaaaaa-0000-0000-0000-000000000008', '57', 'حدثنا  عفان  حدثنا  حماد بن سلمة  عن  محمد بن عمرو  عن  أبي سلمة  أن  فاطمة  رضي الله عنها  قالت  لأبي بكر  من يرثك إذا مت قال ولدي وأهلي قالت فما لنا لا نرث النبي  صلى الله عليه وسلم  قال سمعت النبي  صلى الله عليه وسلم  يقول  إن النبي لا يورث ولكني  أعول  من كان رسول الله  صلى الله عليه وسلم  يعول وأنفق على من كان رسول الله  صلى الله عليه وسلم  ينفق', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0780a864-1e94-5ead-a7a2-9739e0b24b85', 'aaaaaaaa-0000-0000-0000-000000000008', '58', 'حدثنا  عفان  حدثنا  يزيد بن زريع  حدثنا  يونس بن عبيد  عن  حميد بن هلال  عن  عبد الله بن مطرف بن الشخير  أنه حدثهم عن  أبي برزة الأسلمي  أنه قال  كنا عند  أبي بكر الصديق  رضي الله عنه  في عمله فغضب على رجل من المسلمين فاشتد غضبه عليه جدا فلما رأيت ذلك قلت يا خليفة رسول الله أضرب عنقه فلما ذكرت القتل  صرف  عن ذلك الحديث أجمع إلى غير ذلك من النحو فلما تفرقنا أرسل إلي بعد ذلك  أبو بكر الصديق  رضي الله عنه  فقال يا  أبا برزة  ما قلت قال ونسيت الذي قلت قلت ذكرنيه قال أما تذكر ما قلت قال قلت لا والله قال أرأيت حين رأيتني غضبت على الرجل فقلت أضرب عنقه يا خليفة رسول الله أما تذكر ذاك أوكنت فاعلا ذاك قال قلت نعم والله والآن إن أمرتني فعلت قال ويحك  أو ويلك  إن تلك والله  ما هي لأحد بعد  محمد  صلى الله عليه وسلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ff5141f2-a6a5-5f04-a8cc-6bdef27f39d9', 'aaaaaaaa-0000-0000-0000-000000000008', '59', 'حدثنا  عفان  قال حدثنا  حماد بن سلمة  قال حدثنا  ابن أبي عتيق  عن  أبيه  قال إن  أبا بكر الصديق  رضي الله عنه  قال  قال رسول الله  صلى الله عليه وسلم  السواك  مطهرة  للفم مرضاة للرب', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('32fb6e4e-d1d8-5924-aca2-7529c05abdbf', 'aaaaaaaa-0000-0000-0000-000000000008', '60', 'حدثنا  عفان  قال حدثنا  شعبة  عن  يعلى بن عطاء  قال سمعت  عمرو بن عاصم بن عبد الله  قال سمعت  أبا هريرة  يقول  قال  أبو بكر  يا رسول الله قل لي شيئا أقوله إذا أصبحت وإذا أمسيت قال قل  اللهم عالم الغيب والشهادة  فاطر  السموات والأرض رب كل  شيء ومليكه أشهد أن لا إله إلا أنت أعوذ بك من شر نفسي ومن شر الشيطان  وشركه  وأمره أن يقوله إذا أصبح وإذا أمسى وإذا أخذ  مضجعه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c1fd71aa-460d-51e6-bd03-66ece1791fe6', 'aaaaaaaa-0000-0000-0000-000000000008', '61', 'حدثنا  محمد بن يزيد  حدثنا  نافع بن عمر الجمحي  عن  عبد الله بن أبي مليكة  قال  قيل  لأبي بكر  رضي الله عنه  يا خليفة الله فقال  بل خليفة  محمد  صلى الله عليه وسلم  وأنا أرضى به', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3e95d7e6-147a-5b53-ba1b-07a2828e7929', 'aaaaaaaa-0000-0000-0000-000000000008', '62', 'حدثنا  موسى بن داود  حدثنا  عبد الله بن المؤمل  عن  ابن أبي مليكة  قال  كان ربما سقط  الخطام  من يد  أبي بكر الصديق  رضي الله عنه  قال فيضرب بذراع ناقته فينيخها فيأخذه قال فقالوا له أفلا أمرتنا نناولكه فقال إن حبيبي رسول الله  صلى الله عليه وسلم  أمرني أن لا أسأل الناس شيئا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('04b52ea2-87b7-588d-a9e7-7ec5ed6bd9a0', 'aaaaaaaa-0000-0000-0000-000000000008', '63', 'حدثنا  عبد الرزاق  أخبرنا  سفيان  عن  عمرو بن مرة  عن  أبي عبيدة  عن  أبي بكر  رضي الله عنه  قال  قام  أبو بكر  رضي الله عنه  بعد وفاة رسول الله  صلى الله عليه وسلم  بعام فقال قام فينا رسول الله  صلى الله عليه وسلم  عام الأول فقال إن ابن  آدم  لم يعط شيئا أفضل من العافية  فاسألوا الله العافية وعليكم بالصدق  والبر  فإنهما في الجنة وإياكم والكذب والفجور فإنهما في النار', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9b56ef03-f3c7-574b-b843-4e0d8bf78394', 'aaaaaaaa-0000-0000-0000-000000000008', '64', 'حدثنا  محمد بن يزيد  قال أخبرنا  سفيان بن حسين  عن  الزهري  عن  عبيد الله بن عبد الله بن عتبة بن مسعود  عن  أبي هريرة  رضي الله عنه  عن النبي  صلى الله عليه وسلم  قال  أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله فإذا قالوها  عصموا  مني دماءهم وأموالهم إلا بحقها وحسابهم على الله تعالى قال فلما كانت الردة قال  عمر  لأبي بكر  رضي الله عنه  تقاتلهم وقد سمعت رسول الله  صلى الله عليه وسلم  يقول كذا وكذا قال فقال  أبو بكر  رضي الله عنه  والله لا أفرق بين الصلاة والزكاة ولأقاتلن من فرق بينهما قال فقاتلنا معه فرأينا ذلك رشدا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4fdef1c8-07d9-5f60-a4d0-72cb58882c81', 'aaaaaaaa-0000-0000-0000-000000000008', '65', 'حدثنا  عبد الله بن نمير  قال أخبرنا  إسماعيل  عن  أبي بكر بن أبي زهير  قال  أخبرت  أن  أبا بكر  قال  يا رسول الله كيف الصلاح بعد هذه الآية  { ليس بأمانيكم ولا أماني  أهل الكتاب  من يعمل سوءا  يجز  به } فكل سوء عملنا جزينا به فقال رسول الله  صلى الله عليه وسلم  غفر الله لك يا  أبا بكر  ألست تمرض ألست تنصب ألست تحزن ألست تصيبك  اللأواء  قال بلى قال فهو ما تجزون به', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1cfa2b95-0b41-564f-b8aa-7aa49db68775', 'aaaaaaaa-0000-0000-0000-000000000008', '66', 'حدثنا  سفيان  قال حدثنا  ابن أبي خالد  عن  أبي بكر بن أبي زهير  أظنه  قال  أبو بكر  يا رسول الله كيف الصلاح بعد هذه الآية قال يرحمك الله يا  أبا بكر  ألست تمرض ألست تحزن ألست تصيبك  اللأواء  قال بلى قال فإن ذاك بذاك  حدثنا  يعلى بن عبيد  حدثنا  إسماعيل  عن  أبي بكر الثقفي  قال قال  أبو بكر  يا رسول الله كيف الصلاح بعد هذه الآية  { من يعمل سوءا يجز به } فذكر الحديث', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e6b4266c-1424-597e-a258-5f59cdff27dc', 'aaaaaaaa-0000-0000-0000-000000000008', '67', 'حدثنا  وكيع  حدثنا  ابن أبي خالد  عن  أبي بكر بن أبي زهير الثقفي  قال  لما نزلت  { ليس بأمانيكم ولا أماني  أهل الكتاب  من يعمل سوءا  يجز  به } قال فقال  أبو بكر  يا رسول الله إنا  لنجازى  بكل سوء نعمله فقال رسول الله  صلى الله عليه وسلم  يرحمك الله يا  أبا بكر  ألست تنصب ألست تحزن ألست تصيبك  اللأواء  فهذا ما تجزون به', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a7180165-091f-51e1-9680-d8efb4fb0ab3', 'aaaaaaaa-0000-0000-0000-000000000008', '68', 'حدثنا  أبو كامل  حدثنا  حماد بن سلمة  قال  أخذت هذا الكتاب من  ثمامة بن عبد الله بن أنس  عن  أنس بن مالك  أن  أبا بكر  رضي الله عنه  كتب لهم إن هذه فرائض  الصدقة  التي فرض رسول الله  صلى الله عليه وسلم  على المسلمين التي أمر الله عز وجل بها رسول الله  صلى الله عليه وسلم  فمن سئلها من المسلمين على وجهها فليعطها ومن سئل فوق ذلك فلا يعطه فيما دون خمس وعشرين من الإبل  ففي كل خمس  ذود  شاة فإذا بلغت خمسا وعشرين ففيها  ابنة مخاض  إلى خمس وثلاثين فإن لم تكن  ابنة مخاض  فابن لبون  ذكر فإذا بلغت ستة وثلاثين ففيها  ابنة لبون  إلى خمس  وأربعين فإذا بلغت ستة وأربعين ففيها  حقة  طروقة الفحل  إلى ستين فإذا بلغت إحدى وستين ففيها  جذعة  إلى خمس وسبعين فإذا بلغت ستة وسبعين ففيها  بنتا لبون  إلى تسعين فإذا بلغت إحدى وتسعين ففيها  حقتان  طروقتا الفحل  إلى عشرين ومائة فإن زادت على عشرين ومائة ففي كل أربعين  ابنة لبون  وفي كل خمسين  حقة  فإذا  تباين  أسنان الإبل في فرائض  الصدقات  فمن بلغت عنده  صدقة  الجذعة  وليست عنده  جذعة  وعنده  حقة  فإنها تقبل منه ويجعل معها شاتين إن استيسرتا له أو عشرين درهما ومن بلغت عنده  صدقة  الحقة  وليست عنده إلا  جذعة  فإنها تقبل منه ويعطيه  المصدق  عشرين درهما أو شاتين ومن بلغت عنده  صدقة  الحقة  وليست عنده وعنده  بنت لبون  فإنها تقبل منه ويجعل معها شاتين إن استيسرتا له أو عشرين درهما ومن بلغت عنده  صدقة  ابنة لبون  وليست عنده إلا  حقة  فإنها تقبل منه ويعطيه  المصدق  عشرين درهما أو شاتين ومن بلغت عنده  صدقة  ابنة لبون  وليست عنده  ابنة لبون  وعنده  ابنة مخاض  فإنها تقبل منه ويجعل معها شاتين إن استيسرتا له أو عشرين درهما ومن بلغت  صدقته  بنت مخاض  وليس عنده إلا  ابن لبون  ذكر فإنه يقبل منه وليس معه شيء ومن لم يكن عنده إلا أربع من الإبل فليس فيها شيء إلا أن يشاء ربها وفي  صدقة  الغنم في  سائمتها  إذا كانت أربعين ففيها شاة إلى عشرين ومائة فإن زادت ففيها شاتان إلى مائتين فإذا زادت واحدة ففيها ثلاث شياه إلى ثلاث مائة فإذا زادت ففي كل مائة شاة ولا تؤخذ في  الصدقة  هرمة  ولا ذات  عوار  ولا  تيس  إلا أن يشاء المصدق ولا يجمع بين متفرق ولا يفرق بين مجتمع خشية  الصدقة  وما كان من خليطين فإنهما يتراجعان بينهما بالسوية وإذا كانت  سائمة  الرجل ناقصة من أربعين شاة واحدة فليس فيها شيء إلا أن يشاء ربها وفي الرقة ربع  العشر  فإذا لم يكن المال إلا تسعين ومائة درهم فليس فيها شيء إلا أن يشاء ربها', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('152c5c26-77f2-52d3-bf15-b6d744848239', 'aaaaaaaa-0000-0000-0000-000000000008', '69', 'حدثنا  عبد الرزاق  قال  أهل  مكة  يقولون أخذ  ابن جريج  الصلاة من  عطاء  وأخذها  عطاء  من  ابن الزبير  وأخذها  ابن الزبير  من  أبي بكر  وأخذها  أبو بكر  من النبي  صلى الله عليه وسلم  ما رأيت أحدا أحسن صلاة من  ابن جريج', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f7b0edc9-dfa6-55fd-8c5d-5d4783b39c96', 'aaaaaaaa-0000-0000-0000-000000000008', '70', 'حدثنا  عبد الرزاق  قال أخبرنا  معمر  عن  الزهري  عن  سالم  عن  ابن عمر  عن  عمر  قال  تأيمت  حفصة بنت عمر  من  خنيس  أو  حذيفة بن حذافة  شك  عبد الرزاق  وكان من  أصحاب النبي  صلى الله عليه وسلم  ممن شهد  بدرا  فتوفي  بالمدينة  قال فلقيت  عثمان بن عفان  فعرضت عليه  حفصة  فقلت إن شئت أنكحتك  حفصة  قال سأنظر في ذلك فلبثت  ليالي فلقيني فقال ما أريد أن أتزوج يومي هذا قال  عمر  فلقيت  أبا بكر  رضي الله عنه  فقلت إن شئت أنكحتك  حفصة ابنة عمر  فلم يرجع إلي شيئا فكنت  أوجد  عليه مني على  عثمان  فلبثت  ليالي فخطبها إلي رسول الله  صلى الله عليه وسلم  فأنكحتها إياه فلقيني  أبو بكر  رضي الله عنه  فقال لعلك وجدت علي حين عرضت علي  حفصة  فلم أرجع إليك شيئا قال قلت نعم قال فإنه لم يمنعني أن أرجع إليك شيئا حين  عرضتها  علي إلا أني  سمعت رسول الله  صلى الله عليه وسلم  يذكرها ولم أكن لأفشي سر رسول الله  صلى الله عليه وسلم  ولو تركها لنكحتها', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9e93aca6-a0e2-524d-b1fa-b29bb9c80154', 'aaaaaaaa-0000-0000-0000-000000000008', '71', 'حدثنا  إسحاق بن سليمان  قال سمعت  المغيرة بن مسلم أبا سلمة  عن  فرقد السبخي  عن  مرة الطيب  عن  أبي بكر الصديق  رضي الله عنه  قال  قال رسول الله  صلى الله عليه وسلم  لا يدخل الجنة سيئ  الملكة  فقال رجل يا رسول الله أليس أخبرتنا أن هذه الأمة أكثر الأمم مملوكين وأيتاما قال بلى فأكرموهم  كرامة  أولادكم وأطعموهم مما تأكلون قالوا فما ينفعنا في الدنيا يا رسول الله قال فرس صالح ترتبطه تقاتل عليه في سبيل  الله  ومملوك  يكفيك فإذا صلى فهو أخوك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('94a206d7-4c84-5d20-a4dd-5c09954b15bd', 'aaaaaaaa-0000-0000-0000-000000000008', '72', 'حدثنا  عثمان بن عمر  قال أخبرنا  يونس  عن  الزهري  قال أخبرني  ابن السباق  قال أخبرني  زيد بن ثابت  أن  أبا بكر  رضي الله عنه  أرسل إليه مقتل أهل  اليمامة  فإذا  عمر  عنده فقال  أبو بكر  إن  عمر  أتاني فقال إن القتل قد  استحر  بأهل  اليمامة  من قراء القرآن من المسلمين وأنا أخشى أن  يستحر  القتل بالقراء في المواطن فيذهب قرآن كثير لا  يوعى وإني أرى  أن تأمر بجمع القرآن فقلت  لعمر  وكيف أفعل شيئا لم يفعله رسول الله  صلى الله عليه وسلم  فقال هو والله خير فلم يزل يراجعني في ذلك حتى شرح الله بذلك صدري ورأيت فيه الذي رأى  عمر  قال  زيد  وعمر  عنده جالس لا يتكلم فقال  أبو بكر  رضي الله عنه  إنك شاب عاقل لا نتهمك وقد كنت تكتب الوحي لرسول الله  صلى الله عليه وسلم  فاجمعه قال  زيد  فوالله لو كلفوني نقل جبل من الجبال ما كان بأثقل علي مما أمرني به من جمع القرآن فقلت كيف تفعلون شيئا لم يفعله رسول الله  صلى الله عليه وسلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6bf5f3f2-7f77-52c2-be85-5e36bffc4cb7', 'aaaaaaaa-0000-0000-0000-000000000008', '73', 'حدثنا  يحيى بن حماد  حدثنا  أبو عوانة  عن  الأعمش  عن  إسماعيل بن رجاء  عن  عمير  مولى  العباس  عن  ابن عباس  قال  لما قبض رسول الله  صلى الله عليه وسلم  واستخلف  أبو بكر  خاصم  العباس  عليا  في أشياء تركها رسول الله  صلى الله عليه وسلم  فقال  أبو بكر  رضي الله عنه  شيء تركه رسول الله  صلى الله عليه وسلم  فلم يحركه فلا أحركه فلما استخلف  عمر  اختصما إليه فقال شيء لم يحركه  أبو بكر  فلست أحركه قال فلما استخلف  عثمان  رضي الله عنه  اختصما إليه قال فأسكت  عثمان  ونكس رأسه قال  ابن عباس  فخشيت أن يأخذه فضربت بيدي بين كتفي  العباس  فقلت يا  أبت أقسمت عليك إلا سلمته  لعلي  قال فسلمه له', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('15231aac-644d-5e29-b54b-e4bcf1c99144', 'aaaaaaaa-0000-0000-0000-000000000008', '74', 'حدثنا  يحيى بن حماد  قال حدثنا  أبو عوانة  عن  عاصم بن كليب  قال حدثني  شيخ  من  قريش  من  بني تيم  قال حدثني  فلان وفلان وقال فعد ستة  أو سبعة  كلهم من  قريش  فيهم  عبد الله بن الزبير  قال  بينا نحن جلوس عند  عمر  إذ دخل  علي  والعباس  رضي الله عنهما  قد ارتفعت أصواتهما فقال  عمر  مه  يا  عباس  قد علمت ما تقول تقول ابن أخي ولي  شطر  المال وقد علمت ما تقول يا  علي  تقول ابنته تحتي ولها  شطر  المال وهذا ما كان في يدي رسول الله  صلى الله عليه وسلم  فقد رأينا كيف كان يصنع فيه فوليه  أبو بكر  رضي الله عنه  من بعده فعمل فيه بعمل رسول الله  صلى الله عليه وسلم  ثم وليته من بعد  أبي بكر  رضي الله عنه  فأحلف بالله لأجهدن أن أعمل فيه بعمل رسول الله وعمل  أبي بكر  ثم  قال حدثني  أبو بكر  رضي الله عنه  وحلف بأنه لصادق أنه سمع النبي  صلى الله عليه وسلم  يقول إن النبي  لا يورث وإنما ميراثه في فقراء المسلمين والمساكين  و حدثني  أبو بكر  رضي الله عنه  وحلف بالله إنه صادق أن النبي  صلى الله عليه وسلم  قال إن النبي  لا يموت حتى يؤمه بعض أمته  وهذا ما كان في يدي رسول الله  صلى الله عليه وسلم  فقد رأينا كيف كان يصنع فيه فإن شئتما أعطيتكما لتعملا فيه بعمل رسول الله  صلى الله عليه وسلم  وعمل  أبي بكر  حتى أدفعه إليكما قال فخلوا ثم جاءا فقال  العباس  ادفعه إلى  علي  فإني قد طبت نفسا به له', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('27eb8881-6400-591c-abae-c637068fe084', 'aaaaaaaa-0000-0000-0000-000000000008', '75', 'حدثنا  عبد الوهاب بن عطاء  قال أخبرنا  محمد بن عمرو  عن  أبي سلمة  عن  أبي هريرة  أن  فاطمة  رضي الله عنها  جاءت  أبا بكر  وعمر  رضي الله عنهما  تطلب ميراثها من رسول الله  صلى الله عليه وسلم  فقالا إنا سمعنا رسول الله  صلى الله عليه وسلم  يقول  إني لا أورث', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8e3ca76f-d341-5ba6-a0ce-b88680502d26', 'aaaaaaaa-0000-0000-0000-000000000008', '76', 'حدثنا  هاشم بن القاسم  قال حدثنا  عيسى يعني ابن المسيب  عن  قيس بن أبي حازم  قال  إني لجالس عند  أبي بكر الصديق  رضي الله عنه  خليفة رسول الله  صلى الله عليه وسلم  بعد وفاة النبي  صلى الله عليه وسلم  بشهر فذكر قصة فنودي في الناس أن الصلاة جامعة وهي أول صلاة في المسلمين نودي بها إن الصلاة جامعة فاجتمع الناس فصعد المنبر شيئا صنع له كان يخطب عليه وهي أول خطبة خطبها في الإسلام قال فحمد الله وأثنى عليه ثم قال يا أيها الناس ولوددت أن هذا كفانيه غيري ولئن أخذتموني بسنة نبيكم  صلى الله عليه وسلم  ما أطيقها  إن كان لمعصوما من الشيطان وإن كان لينزل عليه الوحي من السماء', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c6c11d34-5a8a-5382-831d-7c5698f33838', 'aaaaaaaa-0000-0000-0000-000000000008', '77', 'حدثنا  هاشم بن القاسم  حدثنا  شيبان  عن  ليث  عن  مجاهد  قال  قال  أبو بكر الصديق  رضي الله عنه  أمرني رسول الله  صلى الله عليه وسلم  أن أقول إذا أصبحت وإذا أمسيت وإذا أخذت  مضجعي  من الليل  اللهم فاطر السموات والأرض عالم الغيب والشهادة أنت رب كل شيء ومليكه أشهد أن لا إله إلا أنت وحدك لا شريك لك وأن  محمدا  عبدك ورسولك أعوذ بك من شر نفسي وشر الشيطان وشركه وأن أقترف على نفسي سوءا أو أجره إلى مسلم  آخر مسند  أبي بكر الصديق  رضي الله عنه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dabd8828-e5fc-5db5-b116-598670a4af45', 'aaaaaaaa-0000-0000-0000-000000000008', '78', 'حدثنا  عبد الرحمن بن مهدي  عن  سفيان  عن  أبي إسحاق  عن  حارثة  قال  جاء ناس من أهل  الشام  إلى  عمر  رضي الله عنه  فقالوا إنا قد أصبنا أموالا وخيلا ورقيقا نحب أن يكون لنا فيها زكاة وطهور قال ما فعله صاحباي قبلي فأفعله واستشار  أصحاب محمد  صلى الله عليه وسلم  وفيهم  علي  رضي الله عنه  فقال  علي  هو حسن إن لم يكن  جزية  راتبة يؤخذون بها من بعدك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('13b5d19a-b964-5013-8d0e-c6f3ab312f65', 'aaaaaaaa-0000-0000-0000-000000000008', '79', 'حدثنا  محمد بن جعفر  قال حدثنا  شعبة  عن  الحكم  عن  أبي وائل  أن  الصبي بن معبد  كان نصرانيا  تغلبيا أعرابيا فأسلم فسأل أي العمل أفضل فقيل له الجهاد في سبيل الله عز وجل فأراد أن يجاهد فقيل له حججت فقال لا فقيل حج واعتمر ثم جاهد فانطلق حتى إذا كان  بالحوابط  أهل بهما جميعا فرآه  زيد بن صوحان  وسلمان بن ربيعة  فقالا لهو أضل من جمله  أو ما هو بأهدى من ناقته  فانطلق إلى  عمر  رضي الله عنه  فأخبره بقولهما فقال  هديت لسنة نبيك  صلى الله عليه وسلم  قال  الحكم  فقلت  لأبي وائل  حدثك  الصبي  فقال نعم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4b626c27-1f24-5619-ab8f-2c7789eb6c83', 'aaaaaaaa-0000-0000-0000-000000000008', '80', 'حدثنا  عفان  حدثنا  شعبة  عن  أبي إسحاق  قال سمعت  عمرو بن ميمون  قال  صلى بنا  عمر  بجمع  الصبح ثم وقف وقال إن المشركين كانوا لا يفيضون حتى تطلع الشمس وإن رسول الله  صلى الله عليه وسلم  خالفهم ثم  أفاض قبل أن تطلع الشمس', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b75b13d9-1329-54e9-a9e1-186ba9a7605f', 'aaaaaaaa-0000-0000-0000-000000000008', '81', 'حدثنا  عفان  حدثنا  عبد الواحد بن زياد  قال حدثنا  عاصم بن كليب  قال قال  أبي  فحدثنا به  ابن عباس  رضي الله عنهما  قال وما أعجبك من ذلك كان  عمر  رضي الله عنه  إذا دعا الأشياخ من  أصحاب محمد  صلى الله عليه وسلم  دعاني معهم فقال لا تتكلم حتى يتكلموا قال فدعانا ذات يوم  أو ذات ليلة  فقال إن رسول الله  صلى الله عليه وسلم  قال في ليلة القدر ما قد علمتم  فالتمسوها  في العشر الأواخر  وترا  ففي أي الوتر ترونها', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e3008701-ffbe-5ab7-8e93-e458fbde9a5a', 'aaaaaaaa-0000-0000-0000-000000000008', '82', 'حدثنا  محمد بن جعفر  حدثنا  شعبة  قال سمعت  عاصم بن عمرو البجلي  يحدث عن  رجل  من القوم الذين سألوا  عمر بن الخطاب  فقالوا له إنما أتيناك نسألك عن ثلاث عن صلاة الرجل في بيته تطوعا وعن الغسل من الجنابة وعن الرجل ما يصلح له من امرأته إذا كانت حائضا فقال  أسحار أنتم لقد سألتموني عن شيء ما سألني عنه أحد منذ سألت عنه رسول الله  صلى الله عليه وسلم  فقال  صلاة الرجل في بيته تطوعا نور فمن شاء نور بيته وقال في الغسل من الجنابة يغسل فرجه ثم يتوضأ ثم يفيض على رأسه ثلاثا وقال في الحائض له ما فوق الإزار', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a68a4d25-a950-5e8d-b323-252ef7902143', 'aaaaaaaa-0000-0000-0000-000000000008', '83', 'حدثنا  قتيبة بن سعيد  حدثنا  ابن لهيعة  عن  أبي النضر  عن  أبي سلمة  عن  ابن عمر  رضي الله عنه  أنه قال  رأيت  سعد بن أبي وقاص  يمسح على خفيه  بالعراق  حين يتوضأ فأنكرت ذلك عليه قال فلما اجتمعنا عند  عمر بن الخطاب  رضي الله عنه  قال لي سل أباك عما أنكرت علي من مسح الخفين قال فذكرت ذلك له فقال إذا حدثك  سعد  بشيء فلا ترد عليه فإن رسول الله  صلى الله عليه وسلم  كان  يمسح على الخفين', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('88d12a57-8a0c-5ea8-a1bf-63ba7325d702', 'aaaaaaaa-0000-0000-0000-000000000008', '84', 'حدثنا  هارون بن معروف  قال حدثنا  ابن وهب  عن  عمرو بن الحارث  عن  أبي النضر  عن  أبي سلمة بن عبد الرحمن  عن  عبد الله بن عمر  عن  سعد بن أبي وقاص  عن رسول الله  صلى الله عليه وسلم  أنه  مسح على الخفين وأن  عبد الله بن عمر  سأل  عمر  رضي الله عنه  عن ذلك فقال نعم إذا حدثك  سعد  عن رسول الله  صلى الله عليه وسلم  شيئا فلا تسأل عنه غيره', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e7596972-cffd-551b-8d69-79f6aa68ffd2', 'aaaaaaaa-0000-0000-0000-000000000008', '85', 'حدثنا  عفان  حدثنا  همام بن يحيى  قال حدثنا  قتادة  عن  سالم بن أبي الجعد الغطفاني  عن  معدان بن أبي طلحة اليعمري  أن  عمر بن الخطاب  رضي الله عنه  قام على المنبر يوم الجمعة فحمد الله وأثنى عليه ثم ذكر رسول الله  صلى الله عليه وسلم  وذكر  أبا بكر  رضي الله عنه  ثم قال رأيت رؤيا لا أراها إلا لحضور أجلي رأيت كأن ديكا نقرني نقرتين قال وذكر لي أنه ديك أحمر فقصصتها على  أسماء بنت عميس  امرأة  أبي بكر  رضي الله عنهما  فقالت يقتلك رجل من  العجم  قال وإن الناس يأمرونني أن أستخلف وإن الله لم يكن ليضيع دينه وخلافته التي بعث بها نبيه  صلى الله عليه وسلم  وإن يعجل بي أمر فإن الشورى في هؤلاء الستة الذين مات نبي الله  صلى الله عليه وسلم  وهو عنهم راض فمن  بايعتم  منهم فاسمعوا له وأطيعوا وإني أعلم أن أناسا سيطعنون في هذا الأمر أنا قاتلتهم بيدي هذه على الإسلام أولئك أعداء الله الكفار الضلال وايم الله ما أترك فيما عهد إلي ربي فاستخلفني شيئا أهم إلي من  الكلالة  وايم الله ما أغلظ لي نبي الله  صلى الله عليه وسلم  في شيء منذ صحبته أشد ما أغلظ لي في شأن  الكلالة  حتى طعن بإصبعه في صدري وقال  تكفيك  آية الصيف  التي نزلت في آخر سورة  النساء  وإني إن أعش  فسأقضي فيها بقضاء يعلمه من يقرأ ومن لا يقرأ وإني أشهد الله على أمراء  الأمصار  إني إنما بعثتهم ليعلموا الناس دينهم ويبينوا لهم سنة نبيهم  صلى الله عليه وسلم  ويرفعوا إلي ما عمي عليهم ثم إنكم أيها الناس تأكلون من شجرتين لا  أراهما إلا خبيثتين هذا الثوم والبصل وايم الله لقد كنت أرى نبي الله  صلى الله عليه وسلم  يجد ريحهما من الرجل فيأمر به فيؤخذ بيده فيخرج به من المسجد حتى يؤتى به  البقيع  فمن أكلهما لا بد فليمتهما طبخا قال فخطب الناس يوم الجمعة وأصيب يوم الأربعاء', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a3d288f-3816-5313-9cb4-bc4437fd35ad', 'aaaaaaaa-0000-0000-0000-000000000008', '86', 'حدثنا  يعقوب  حدثنا  أبي  عن  ابن إسحاق  قال حدثني  نافع  مولى  عبد الله بن عمر  عن  عبد الله بن عمر  قال  خرجت أنا  والزبير  والمقداد بن الأسود  إلى أموالنا  بخيبر  نتعاهدها فلما قدمناها تفرقنا في أموالنا قال فعدي علي تحت الليل وأنا نائم على فراشي  ففدعت  يداي من مرفقي فلما أصبحت استصرخ علي صاحباي فأتياني فسألاني عمن صنع هذا بك قلت لا أدري قال فأصلحا من يدي ثم قدموا بي على  عمر  فقال هذا عمل  يهود  ثم قام في الناس خطيبا فقال أيها الناس إن رسول الله  صلى الله عليه وسلم  كان  عامل  يهود خيبر  على أنا نخرجهم إذا شئنا وقد عدوا على  عبد الله بن عمر  رضي الله عنه  ففدعوا  يديه كما بلغكم مع عدوتهم على  الأنصار  قبله لا نشك أنهم أصحابهم ليس لنا هناك عدو غيرهم فمن كان له مال  بخيبر  فليلحق به فإني  مخرج  يهود  فأخرجهم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d40080ed-846d-505c-ba8e-44897d31d81b', 'aaaaaaaa-0000-0000-0000-000000000008', '87', 'حدثنا  حسن بن موسى  وحسين بن محمد  قالا حدثنا  شيبان  عن  يحيى  عن  أبي سلمة  عن  أبي هريرة  أن  عمر بن الخطاب  رضي الله عنه  بينا هو يخطب يوم الجمعة إذ جاء  رجل  فقال  عمر  لم تحتبسون عن الصلاة فقال الرجل ما هو إلا أن سمعت النداء فتوضأت فقال أيضا أولم تسمعوا أن رسول الله  صلى الله عليه وسلم  يقول  إذا  راح  أحدكم إلى الجمعة فليغتسل', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ace4a63d-ca3f-5322-ac91-b656109df398', 'aaaaaaaa-0000-0000-0000-000000000008', '88', 'حدثنا  حسن بن موسى  قال حدثنا  زهير  قال حدثنا  عاصم الأحول  عن  أبي عثمان  قال  جاءنا كتاب  عمر  رضي الله عنه  ونحن  بأذربيجان  يا  عتبة بن فرقد  وإياكم والتنعم وزي أهل الشرك ولبوس الحرير فإن رسول الله  صلى الله عليه وسلم  نهانا عن لبوس الحرير وقال إلا هكذا ورفع لنا رسول الله  صلى الله عليه وسلم  إصبعيه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9cfb2088-c09b-5d0e-9ece-e8f4a825ea9f', 'aaaaaaaa-0000-0000-0000-000000000008', '89', 'حدثنا  حسن  قال حدثنا  ابن لهيعة  حدثنا  أبو الأسود  أنه سمع  محمد بن عبد الرحمن ابن لبيبة  يحدث عن  أبي سنان الدؤلي  أنه دخل على  عمر بن الخطاب  رضي الله عنه  وعنده  نفر  من  المهاجرين  الأولين فأرسل  عمر  إلى  سفط  أتي به من قلعة من  العراق  فكان فيه خاتم فأخذه بعض بنيه فأدخله في  فيه فانتزعه  عمر  منه ثم بكى  عمر  رضي الله عنه  فقال له من عنده لم تبكي وقد فتح الله لك وأظهرك على عدوك وأقر عينك فقال  عمر  رضي الله عنه  إني سمعت رسول الله  صلى الله عليه وسلم  يقول  لا تفتح الدنيا على أحد إلا ألقى الله عز وجل بينهم العداوة والبغضاء إلى يوم القيامة وأنا أشفق من ذلك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('84fdfd7e-9c63-59a7-b2d1-968d1aeace8f', 'aaaaaaaa-0000-0000-0000-000000000008', '90', 'حدثنا  يعقوب  حدثنا  أبي  عن  ابن إسحاق  حدثني  نافع  عن  عبد الله بن عمر  عن  أبيه  قال  سألت رسول الله  صلى الله عليه وسلم  كيف يصنع أحدنا إذا هو أجنب ثم أراد أن ينام قبل أن يغتسل قال فقال رسول الله  صلى الله عليه وسلم  ليتوضأ وضوءه للصلاة ثم لينم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1ee7258f-7855-5410-bc36-cede882aa4d5', 'aaaaaaaa-0000-0000-0000-000000000008', '91', 'حدثنا  يعقوب  حدثنا  أبي  عن  ابن إسحاق  حدثني  الزهري  عن  عبيد الله بن عبد الله بن عتبة بن مسعود  عن  عبد الله بن عباس  رضي الله عنهما  قال سمعت  عمر بن الخطاب  رضي الله عنه  يقول  لما توفي  عبد الله بن أبي  دعي رسول الله  صلى الله عليه وسلم  للصلاة عليه فقام إليه فلما وقف عليه يريد الصلاة تحولت حتى قمت في صدره فقلت يا رسول الله أعلى عدو الله  عبد الله بن أبي  القائل يوم كذا كذا وكذا يعدد أيامه قال ورسول الله  صلى الله عليه وسلم  يتبسم حتى إذا أكثرت عليه قال أخر عني يا  عمر  إني خيرت فاخترت وقد قيل  { استغفر لهم أو لا تستغفر لهم إن تستغفر لهم سبعين مرة فلن يغفر الله لهم } لو أعلم أني إن زدت على السبعين غفر له لزدت قال ثم صلى عليه ومشى معه فقام على قبره حتى فرغ منه قال فعجب لي وجراءتي على رسول الله  صلى الله عليه وسلم  والله ورسوله أعلم قال فوالله ما كان إلا يسيرا حتى نزلت هاتان الآيتان  { ولا تصل على أحد منهم مات أبدا ولا تقم على قبره إنهم كفروا بالله ورسوله وماتوا وهم فاسقون } فما صلى رسول الله  صلى الله عليه وسلم  بعده على منافق ولا قام على قبره حتى قبضه الله عز وجل', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0f5a5e32-2528-5f3b-ace4-2e1cd200cf95', 'aaaaaaaa-0000-0000-0000-000000000008', '92', 'حدثنا  يعقوب  حدثنا  أبي  عن  ابن إسحاق  كما  حدثني عنه  نافع  مولاه  قال  كان  عبد الله بن عمر  رضي الله عنه  يقول  إذا لم يكن للرجل إلا ثوب واحد  فليأتزر به ثم ليصل فإني سمعت  عمر بن الخطاب  رضي الله عنه  يقول ذلك ويقول لا تلتحفوا بالثوب إذا كان وحده كما تفعل  اليهود  قال  نافع  ولو قلت  لكم  إنه أسند ذلك إلى رسول الله  صلى الله عليه وسلم  لرجوت أن لا أكون كذبت', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('173d87da-67e4-5e4a-9a2c-29fc7c69756f', 'aaaaaaaa-0000-0000-0000-000000000008', '93', 'حدثنا  مؤمل  حدثنا  حماد  قال حدثنا  زياد بن مخراق  عن  شهر  عن  عقبة بن عامر  قال حدثني  عمر  رضي الله عنه  أنه سمع رسول الله  صلى الله عليه وسلم  يقول  من مات يؤمن بالله واليوم الآخر قيل له ادخل الجنة من أي أبواب الجنة الثمانية شئت', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('64a0a07a-d988-54e3-820d-4ea424d81c4a', 'aaaaaaaa-0000-0000-0000-000000000008', '94', 'حدثنا  أسود بن عامر  قال أخبرنا  جعفر يعني الأحمر  عن  مطرف  عن  الحكم  عن  مجاهد  قال  حذف  رجل ابنا له بسيف فقتله فرفع إلى  عمر  فقال لولا أني سمعت رسول الله  صلى الله عليه وسلم  يقول  لا  يقاد  الوالد من ولده لقتلتك قبل أن تبرح', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('87a0085e-c6f9-5f59-8378-e0ec72900725', 'aaaaaaaa-0000-0000-0000-000000000008', '95', 'حدثنا  أسود بن عامر  قال حدثنا  زهير  عن  سليمان الأعمش  حدثنا  إبراهيم  عن  عابس بن ربيعة  قال  رأيت  عمر  نظر إلى الحجر فقال أما والله  لولا أني رأيت رسول الله  صلى الله عليه وسلم  يقبلك ما قبلتك ثم قبله', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('09c87106-2701-55fe-826e-f3189b728053', 'aaaaaaaa-0000-0000-0000-000000000008', '96', 'حدثنا  أبو اليمان  قال أخبرنا  شعيب  عن  الزهري  قال أخبرنا  السائب بن يزيد  ابن أخت  نمر  أن  حويطب بن عبد العزى  أخبره أن  عبد الله بن السعدى  أخبره  أنه قدم على  عمر بن الخطاب  رضي الله عنه  في خلافته فقال له  عمر  ألم أحدث أنك تلي من أعمال الناس أعمالا فإذا أعطيت العمالة كرهتها قال فقلت بلى فقال  عمر  رضي الله عنه  فما تريد إلى ذلك قال قلت إن لي أفراسا وأعبدا وأنا بخير وأريد أن تكون عمالتي  صدقة  على المسلمين فقال  عمر  رضي الله عنه  فلا تفعل فإني قد كنت أردت الذي أردت فكان النبي  صلى الله عليه وسلم  يعطيني العطاء فأقول أعطه أفقر إليه مني حتى أعطاني مرة مالا فقلت أعطه أفقر إليه مني قال فقال له النبي  صلى الله عليه وسلم  خذه فتموله وتصدق به فما جاءك من هذا المال وأنت غير مشرف ولا سائل فخذه وما لا فلا تتبعه نفسك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('03c2c01c-fe33-5661-82f7-91c0e6c4bfe2', 'aaaaaaaa-0000-0000-0000-000000000008', '97', 'حدثنا  سكن بن نافع الباهلي  قال حدثنا  صالح  عن  الزهري  قال حدثني  ربيعة بن دراج  أن  علي بن أبي طالب  رضي الله عنه  سبح  بعد العصر ركعتين في طريق  مكة  فرآه  عمر  رضي الله عنه  فتغيظ عليه ثم قال أما والله لقد علمت أن رسول الله  صلى الله عليه وسلم  نهى عنها', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('04d04007-9841-5f56-85ff-542a7c6f58ca', 'aaaaaaaa-0000-0000-0000-000000000008', '98', 'حدثنا  محمد بن يزيد  حدثنا  محمد بن إسحاق  قال حدثنا  العلاء بن عبد الرحمن بن يعقوب  عن  رجل  من  قريش  من  بني سهم  عن  رجل منهم يقال له  ماجدة  قال  عارمت  غلاما  بمكة  فعض أذني فقطع منها  أو عضضت أذنه فقطعت منها  فلما قدم علينا  أبو بكر  رضي الله عنه  حاجا رفعنا إليه فقال انطلقوا بهما إلى  عمر بن الخطاب  رضي الله عنه  فإن كان الجارح بلغ أن يقتص منه فليقتص قال فلما انتهي بنا إلى  عمر  رضي الله عنه  نظر إلينا فقال نعم قد بلغ هذا أن يقتص منه ادعوا لي  حجاما  فلما ذكر  الحجام  قال أما إني قد سمعت رسول الله  صلى الله عليه وسلم  يقول قد  أعطيت خالتي غلاما وأنا أرجو أن يبارك الله لها فيه وقد نهيتها أن تجعله  حجاما  أو  قصابا  أو صائغا  حدثنا  يعقوب  حدثنا  أبي  عن  ابن إسحاق  قال وحدثني  العلاء بن عبد الرحمن  عن  رجل  من  بني سهم  عن  ابن ماجدة السهمي  أنه قال  حج علينا  أبو بكر  رضي الله عنه  في خلافته فذكر الحديث', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('75724296-6fc1-5056-b9a7-80ac4050d494', 'aaaaaaaa-0000-0000-0000-000000000008', '99', 'حدثنا  عبيدة بن حميد  عن  داود بن أبي هند  عن  أبي نضرة  عن  أبي سعيد  قال  خطب  عمر  رضي الله عنه  الناس فقال إن الله عز وجل رخص لنبيه  صلى الله عليه وسلم  ما شاء وإن نبي الله  صلى الله عليه وسلم  قد مضى لسبيله  فأتموا الحج والعمرة كما أمركم الله عز وجل وحصنوا فروج هذه النساء', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ce61c0a-709a-57a6-8eee-a28227dfa415', 'aaaaaaaa-0000-0000-0000-000000000008', '100', 'حدثنا  عبيدة بن حميد  حدثني  عبيد الله بن عمر  عن  نافع  عن  ابن عمر  عن  عمر بن الخطاب  رضي الله عنه  قال  سئل رسول الله  صلى الله عليه وسلم  أيرقد الرجل إذا  أجنب  قال نعم إذا توضأ', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ac115f85-9ea9-5939-bd24-4dc8d6505f82', 'aaaaaaaa-0000-0000-0000-000000000008', '101', 'حدثنا  الحسن بن يحيى  قال أخبرنا  ابن المبارك  قال حدثنا  معمر  عن  الزهري  عن  ربيعة بن دراج  أن  عليا  رضي الله عنه  صلى بعد العصر ركعتين فتغيظ عليه  عمر  رضي الله عنه  وقال أما علمت أن رسول الله  صلى الله عليه وسلم  كان  ينهانا عنها', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('64cd9070-66ea-5e07-ac5d-755aea31ff02', 'aaaaaaaa-0000-0000-0000-000000000008', '102', 'حدثنا  أبو المغيرة  حدثنا  صفوان  حدثنا  شريح بن عبيد  قال قال  عمر بن الخطاب  رضي الله عنه  خرجت أتعرض رسول الله  صلى الله عليه وسلم  قبل أن أسلم فوجدته قد سبقني إلى المسجد فقمت خلفه فاستفتح سورة  الحاقة  فجعلت أعجب من تأليف القرآن قال فقلت هذا والله شاعر كما قالت  قريش  قال فقرأ  { إنه لقول رسول كريم وما هو بقول شاعر قليلا ما تؤمنون } قال قلت  كاهن  قال  { ولا بقول  كاهن  قليلا ما تذكرون تنزيل من رب العالمين ولو تقول علينا بعض الأقاويل لأخذنا منه باليمين ثم لقطعنا منه الوتين فما منكم من أحد عنه حاجزين } إلى آخر السورة قال فوقع الإسلام في قلبي كل موقع', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('31467817-b07b-52d3-bf21-2eea2b5ccd24', 'aaaaaaaa-0000-0000-0000-000000000008', '103', 'حدثنا  أبو المغيرة  وعصام بن خالد  قالا حدثنا  صفوان  عن  شريح بن عبيد  وراشد بن سعد  وغيرهما  قالوا  لما بلغ  عمر بن الخطاب  رضي الله عنه  سرغ  حدث أن  بالشام  وباء شديدا قال بلغني أن شدة الوباء في  الشام  فقلت إن أدركني أجلي  وأبو عبيدة بن الجراح  حي استخلفته فإن سألني الله لم استخلفته على أمة  محمد  صلى الله عليه وسلم  قلت إني سمعت رسولك  صلى الله عليه وسلم  يقول  إن لكل نبي أمينا وأميني  أبو عبيدة بن الجراح  فأنكر القوم ذلك وقالوا ما بال عليا  قريش  يعنون  بني فهر  ثم قال فإن أدركني أجلي وقد توفي  أبو عبيدة  استخلفت  معاذ بن جبل  فإن سألني ربي عز وجل لم استخلفته قلت سمعت رسولك  صلى الله عليه وسلم  يقول إنه يحشر يوم القيامة بين يدي العلماء  نبذة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a7e6d930-8d85-512d-b99b-cc76479339b5', 'aaaaaaaa-0000-0000-0000-000000000008', '104', 'حدثنا  أبو المغيرة  حدثنا  ابن عياش  قال حدثني  الأوزاعي  وغيره  عن  الزهري  عن  سعيد بن المسيب  عن  عمر بن الخطاب  رضي الله عنه  قال  ولد لأخي  أم سلمة زوج النبي  صلى الله عليه وسلم  غلام فسموه  الوليد  فقال النبي  صلى الله عليه وسلم  سميتموه بأسماء فراعنتكم  ليكونن في هذه الأمة رجل يقال له  الوليد  لهو شر على هذه الأمة من  فرعون  لقومه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2c316292-5b68-5196-8058-22ba8e6cab50', 'aaaaaaaa-0000-0000-0000-000000000008', '105', 'حدثنا  بهز  حدثنا  أبان  عن  قتادة  عن  أبى العالية  عن  ابن عباس  قال  شهد عندي رجال مرضيون منهم  عمر  وأرضاهم عندي  عمر  أن نبي الله  صلى الله عليه وسلم  كان يقول  لا صلاة بعد صلاة العصر حتى تغرب الشمس ولا صلاة بعد صلاة الصبح حتى تطلع الشمس', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c9f5e25e-81fe-5228-b426-124d03dd1ba5', 'aaaaaaaa-0000-0000-0000-000000000008', '106', 'حدثنا  أبو المغيرة  حدثنا  صفوان  حدثنا  عبد الرحمن بن جبير بن نفير  عن  الحارث بن معاوية الكندي  أنه ركب إلى  عمر بن الخطاب  رضي الله عنه  يسأله عن ثلاث  خلال  قال فقدم  المدينة  فسأله  عمر  رضي الله عنه  ما أقدمك قال لأسألك عن ثلاث  خلال  قال وما هن قال ربما كنت أنا والمرأة في بناء ضيق فتحضر الصلاة فإن صليت أنا وهي كانت بحذائي وإن صلت خلفي خرجت من البناء فقال  عمر  تستر بينك وبينها بثوب ثم تصلي بحذائك إن شئت وعن الركعتين بعد العصر فقال نهاني عنهما رسول الله  صلى الله عليه وسلم  قال وعن القصص فإنهم أرادوني على القصص فقال ما شئت كأنه كره أن يمنعه قال إنما أردت أن أنتهي إلى قولك قال أخشى عليك أن تقص فترتفع عليهم في نفسك ثم تقص فترتفع حتى يخيل إليك أنك فوقهم بمنزلة  الثريا  فيضعك الله تحت أقدامهم يوم القيامة بقدر ذلك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7123db16-5239-5e04-8eba-c7949c6dccba', 'aaaaaaaa-0000-0000-0000-000000000008', '107', 'حدثنا  بشر بن شعيب بن أبي حمزة  قال حدثني  أبي  عن  الزهري  قال أخبرني  سالم بن عبد الله  أن  عبد الله بن عمر  أخبره أن  عمر بن الخطاب  رضي الله عنه  قال  سمعت رسول الله  صلى الله عليه وسلم  يقول  إن الله عز وجل ينهاكم أن تحلفوا بآبائكم  قال  عمر  فوالله ما حلفت بها منذ سمعت رسول الله  صلى الله عليه وسلم  نهى عنها ولا تكلمت بها ذاكرا ولا آثرا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('08590fb2-3faa-5e2f-82a6-c548f4f3570f', 'aaaaaaaa-0000-0000-0000-000000000008', '108', 'حدثنا  أبو اليمان  حدثنا  أبو بكر بن عبد الله  عن  راشد بن سعد  عن  عمر بن الخطاب  رضي الله عنه  وحذيفة بن اليمان  أن النبي  صلى الله عليه وسلم  لم يأخذ من الخيل  والرقيق  صدقة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4527f3be-f9fe-536f-8510-58e49e12bce3', 'aaaaaaaa-0000-0000-0000-000000000008', '109', 'حدثنا  علي بن إسحاق  أنبأنا  عبد الله يعني ابن المبارك  أنبأنا  محمد بن سوقة  عن  عبد الله بن دينار  عن  ابن عمر  أن  عمر بن الخطاب  رضي الله عنه  خطب  الناس  بالجابية  فقال قام فينا رسول الله  صلى الله عليه وسلم  مثل مقامي فيكم فقال  استوصوا بأصحابي خيرا ثم الذين يلونهم ثم الذين يلونهم ثم  يفشو الكذب حتى إن الرجل ليبتدئ بالشهادة قبل أن يسألها فمن أراد منكم بحبحة الجنة فليلزم الجماعة فإن الشيطان مع الواحد وهو من  الاثنين أبعد لا يخلون أحدكم بامرأة فإن الشيطان ثالثهما ومن سرته حسنته وساءته سيئته فهو مؤمن', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('36d86968-197b-58e7-b599-b2c241e42ca0', 'aaaaaaaa-0000-0000-0000-000000000008', '110', 'حدثنا  أبو اليمان  حدثنا  أبو بكر  عن  حكيم بن عمير  وضمرة بن حبيب  قالا  قال  عمر بن الخطاب  رضي الله عنه  من سره أن ينظر إلى هدي رسول الله  صلى الله عليه وسلم  فلينظر إلى هدي  عمرو بن الأسود', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5dec1b98-4ae8-5f8f-848e-81d09f60f4cd', 'aaaaaaaa-0000-0000-0000-000000000008', '111', 'حدثنا  أبو سعيد  مولى  بني هاشم  قال حدثنا  زائدة  حدثنا  سماك  عن  عكرمة  عن  ابن عباس  قال قال  عمر  كنا مع رسول الله  صلى الله عليه وسلم  في ركب فقال رجل لا وأبي فقال رجل  لا تحلفوا بآبائكم فالتفت فإذا هو رسول الله  صلى الله عليه وسلم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ff66dcb4-38b1-5cb7-954e-14d0fc846dea', 'aaaaaaaa-0000-0000-0000-000000000008', '112', 'حدثنا  عصام بن خالد  وأبو اليمان  قالا أخبرنا  شعيب بن أبي حمزة  عن  الزهري  قال حدثنا  عبيد الله بن عبد الله بن عتبة بن مسعود  رضي الله عنه  أن  أبا هريرة  قال  لما توفي رسول الله  صلى الله عليه وسلم  وكان  أبو بكر  بعده وكفر من كفر من  العرب  قال  عمر  يا  أبا بكر  كيف تقاتل الناس وقد قال رسول الله  صلى الله عليه وسلم  أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله فمن قال لا إله إلا الله فقد عصم مني ماله ونفسه إلا بحقه وحسابه على الله تعالى قال  أبو بكر  والله لأقاتلن  قال  أبو اليمان  لأقتلن  من فرق بين الصلاة والزكاة فإن الزكاة حق المال والله لو منعوني عناقا كانوا يؤدونها إلى رسول الله  صلى الله عليه وسلم  لقاتلتهم على منعها  قال  عمر  فوالله ما هو إلا أن رأيت أن الله عز وجل قد شرح صدر  أبي بكر  رضي الله عنه  للقتال فعرفت أنه الحق', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5d52f0bd-7c34-5bba-a6df-ed8ea101b2bc', 'aaaaaaaa-0000-0000-0000-000000000008', '113', 'حدثنا  أبو المغيرة  حدثنا  الأوزاعي  حدثنا  عمرو بن شعيب  عن  عبد الله بن عمرو بن العاص  عن  عمر بن الخطاب  رضي الله عنه  أن رسول الله  صلى الله عليه وسلم  قال  لا صلاة بعد صلاة الصبح إلى طلوع الشمس ولا بعد العصر حتى تغيب الشمس', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4c84636a-cd9b-56c6-8ef4-74b234a41835', 'aaaaaaaa-0000-0000-0000-000000000008', '114', 'حدثنا  الحكم بن نافع  حدثنا  ابن عياش  عن  أبي سبإ عتبة بن تميم  عن  الوليد بن عامر اليزني  عن  عروة بن مغيث الأنصاري  عن  عمر بن الخطاب  رضي الله عنه  قال  قضى  النبي  صلى الله عليه وسلم  أن صاحب الدابة أحق  بصدرها', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('61f63fc8-dfb2-5c48-94b3-fba0375758f0', 'aaaaaaaa-0000-0000-0000-000000000008', '115', 'حدثنا  أبو اليمان الحكم بن نافع  حدثنا  أبو بكر بن عبد الله  عن  راشد بن سعد  عن  حمرة بن عبد كلال  قال  سار  عمر بن الخطاب  رضي الله عنه  إلى  الشام  بعد مسيره الأول كان إليها حتى إذا شارفها بلغه ومن معه أن الطاعون  فاش  فيها فقال له أصحابه ارجع ولا تقحم عليه فلو نزلتها وهو بها لم نر لك  الشخوص  عنها فانصرف راجعا إلى  المدينة  فعرس  من ليلته تلك وأنا أقرب القوم منه فلما انبعث انبعثت معه في أثره فسمعته يقول ردوني عن  الشام  بعد أن  شارفت  عليه لأن الطاعون فيه ألا وما منصرفي عنه مؤخر في أجلي وما كان قدوميه معجلي عن أجلي ألا ولو قد قدمت  المدينة  ففرغت من حاجات لا بد لي منها لقد سرت حتى أدخل  الشام  ثم أنزل  حمص  فإني سمعت رسول الله  صلى الله عليه وسلم  يقول  ليبعثن الله منها يوم القيامة سبعين ألفا لا حساب عليهم ولا عذاب عليهم مبعثهم فيما بين الزيتون وحائطها في  البرث  الأحمر منها', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9e293592-123d-5a7e-9b9a-2137e6d4bab7', 'aaaaaaaa-0000-0000-0000-000000000008', '116', 'حدثنا  عبد الله بن يزيد  أخبرنا  حيوة  أخبرنا  أبو عقيل  عن  ابن عمه  عن  عقبة بن عامر  أنه خرج مع رسول الله  صلى الله عليه وسلم  في  غزوة  تبوك  فجلس رسول الله  صلى الله عليه وسلم  يوما يحدث أصحابه فقال  من قام إذا استقلت الشمس فتوضأ فأحسن الوضوء ثم قام فصلى ركعتين غفر له خطاياه فكان كما ولدته أمه قال  عقبة بن عامر  فقلت الحمد لله الذي رزقني أن أسمع هذا من رسول الله  صلى الله عليه وسلم  فقال لي  عمر بن الخطاب  رضي الله عنه  وكان تجاهي جالسا أتعجب من هذا فقد قال رسول الله  صلى الله عليه وسلم  أعجب  من هذا قبل أن تأتي فقلت وما ذاك بأبي أنت وأمي فقال  عمر  قال رسول الله  صلى الله عليه وسلم  من توضأ فأحسن الوضوء ثم رفع نظره إلى السماء فقال أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن  محمدا  عبده ورسوله فتحت له ثمانية أبواب الجنة يدخل  من أيها شاء', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2eefa565-96a9-52a4-98d4-f0399c893960', 'aaaaaaaa-0000-0000-0000-000000000008', '117', 'حدثنا  سليمان بن داود يعني أبا داود الطيالسي  قال حدثنا  أبو عوانة  عن  داود الأودي  عن  عبد الرحمن المسلي  عن  الأشعث بن قيس  قال  ضفت  عمر  فتناول امرأته فضربها وقال يا  أشعث  احفظ عني ثلاثا حفظتهن عن رسول الله  صلى الله عليه وسلم  لا تسأل الرجل فيم ضرب امرأته ولا تنم إلا على  وتر  ونسيت الثالثة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('608ac1af-dbca-55f2-9e08-dc8ba8fd8825', 'aaaaaaaa-0000-0000-0000-000000000008', '118', 'حدثنا  عبد الصمد  حدثنا  أبي  حدثنا  يزيد يعني الرشك  عن  معاذة  عن  أم عمرو ابنة عبد الله  أنها سمعت  عبد الله بن الزبير  يقول  سمعت  عمر بن الخطاب  رضي الله عنه  يقول في خطبته إنه سمع من رسول الله  صلى الله عليه وسلم  يقول  من يلبس الحرير في الدنيا فلا  يكساه في الآخرة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('91193bbe-6642-5832-81ae-b5ea89a16301', 'aaaaaaaa-0000-0000-0000-000000000008', '119', 'حدثنا  يحيى بن إسحاق  حدثنا  ابن لهيعة  عن  أبي الزبير  عن  جابر  قال أخبرني  عمر بن الخطاب  رضي الله عنه  قال  سمعت النبي  صلى الله عليه وسلم  يقول  ليسيرن الراكب في جنبات  المدينة  ثم ليقول لقد كان في هذا حاضر من المؤمنين كثير  قال  أبي  أحمد بن حنبل  ولم يجز به  حسن الأشيب  جابرا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9745dc97-8e6f-5bf4-b5e7-4eedc27bbc55', 'aaaaaaaa-0000-0000-0000-000000000008', '120', 'حدثنا  هارون  حدثنا  ابن وهب  حدثني  عمرو بن الحارث  أن  عمر بن السائب  حدثه أن  القاسم بن أبي القاسم السبئي  حدثه عن  قاص الأجناد  بالقسطنطينية  أنه سمعه يحدث أن  عمر بن الخطاب  رضي الله عنه  قال  يا أيها الناس إني سمعت رسول الله  صلى الله عليه وسلم  يقول  من كان يؤمن بالله واليوم الآخر فلا يقعدن على مائدة يدار عليها بالخمر ومن كان يؤمن بالله واليوم الآخر فلا يدخل الحمام إلا  بإزار  ومن كانت تؤمن بالله واليوم الآخر فلا تدخل الحمام', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8e67d03f-6d93-5eb7-b982-db13a1b978e6', 'aaaaaaaa-0000-0000-0000-000000000008', '121', 'حدثنا  أبو سلمة الخزاعي  أنبأنا  ليث  ويونس  حدثنا  ليث  عن  يزيد بن عبد الله بن أسامة بن الهاد  عن  الوليد بن أبي الوليد  عن  عثمان بن عبد الله يعني ابن سراقة  عن  عمر بن الخطاب  رضي الله عنه  قال  سمعت رسول الله  صلى الله عليه وسلم  يقول  من أظل رأس غاز أظله الله يوم القيامة ومن جهز غازيا حتى يستقل كان له مثل أجره حتى يموت  قال قال  يونس  أو يرجع  ومن بنى لله مسجدا يذكر فيه اسم الله تعالى بنى الله له به بيتا في الجنة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a75b89ae-e4a5-5fad-810a-1df5c091e436', 'aaaaaaaa-0000-0000-0000-000000000008', '122', 'حدثنا  عفان  حدثنا  أبو عوانة  عن  سليمان الأعمش  عن  شقيق  عن  سلمان بن ربيعة  قال سمعت  عمر  رضي الله عنه  يقول  قسم رسول الله  صلى الله عليه وسلم  قسمة فقلت يا رسول الله لغير هؤلاء أحق منهم  أهل الصفة  قال فقال رسول الله  صلى الله عليه وسلم  إنكم تخيروني بين أن تسألوني بالفحش وبين أن تبخلوني ولست بباخل', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('837e8d37-3da1-5271-bab6-f58c477c949b', 'aaaaaaaa-0000-0000-0000-000000000008', '123', 'حدثنا  عفان  حدثنا  خالد  عن  يزيد بن أبي زياد  عن  عاصم بن عبيد الله  عن  أبيه  عن  جده  عن  عمر بن الخطاب  رضي الله عنه  قال  رأيت رسول الله  صلى الله عليه وسلم  بعد  الحدث  توضأ ومسح على الخفين', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('038fd832-3660-5b50-9827-bab5e108c3ed', 'aaaaaaaa-0000-0000-0000-000000000008', '124', 'حدثنا  عفان  حدثنا  حماد بن سلمة  عن  علي بن زيد  عن  أبي رافع  أن  عمر بن الخطاب  رضي الله عنه  كان مستندا إلى  ابن عباس  وعنده  ابن عمر  وسعيد بن زيد  رضي الله عنهما  فقال اعلموا أني لم أقل في  الكلالة  شيئا ولم أستخلف من بعدي أحدا وأنه من  أدرك  وفاتي من سبي  العرب  فهو حر من مال الله عز وجل فقال  سعيد بن زيد  أما إنك لو أشرت برجل من المسلمين  لأتمنك الناس وقد فعل ذلك  أبو بكر  رضي الله عنه  وأتمنه الناس فقال  عمر  رضي الله عنه  قد رأيت من أصحابي حرصا سيئا وإني جاعل هذا الأمر إلى هؤلاء  النفر  الستة الذين مات رسول الله  صلى الله عليه وسلم  وهو عنهم راض ثم قال  عمر  رضي الله عنه  لو أدركني أحد رجلين ثم جعلت هذا الأمر إليه لوثقت به  سالم مولى أبي حذيفة  وأبو عبيدة بن الجراح', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c41ebcc7-9617-5ee2-9414-4c6253d2ac0e', 'aaaaaaaa-0000-0000-0000-000000000008', '125', 'حدثنا  عفان  حدثنا  همام  حدثنا  قتادة  حدثني  أبو العالية  عن  ابن عباس  قال  شهد عندي رجال مرضيون فيهم  عمر  رضي الله عنه  وأرضاهم  عندي  عمر  رضي الله عنه  أن رسول الله  صلى الله عليه وسلم  قال  لا صلاة بعد الصبح حتى تطلع الشمس ولا صلاة بعد العصر حتى تغرب الشمس', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c6b59e66-0d5b-5845-9f1e-94632694de09', 'aaaaaaaa-0000-0000-0000-000000000008', '126', 'حدثنا  عفان  حدثنا  وهيب  حدثنا  عبد الله بن عثمان بن خثيم  عن  سعيد بن جبير  عن  ابن عباس  أن  عمر بن الخطاب  رضي الله عنه  أكب  على الركن فقال  إني لأعلم أنك حجر ولو لم أر حبيبي  صلى الله عليه وسلم  قبلك  واستلمك  ما استلمتك ولا قبلتك  و  { لقد كان لكم في رسول الله أسوة حسنة }', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c2a2f087-982a-5816-adc6-052b630fb24c', 'aaaaaaaa-0000-0000-0000-000000000008', '127', 'حدثنا  عفان  حدثنا  حماد  أنبأنا  عمار بن أبي عمار  أن  عمر بن الخطاب  رضي الله عنه  قال  إن رسول الله  صلى الله عليه وسلم  رأى في يد رجل خاتما من ذهب فقال  ألق ذا فألقاه فتختم بخاتم من حديد فقال ذا شر منه فتختم بخاتم من فضة فسكت عنه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0bf687de-fd20-56cf-8999-8bd6809cf8ca', 'aaaaaaaa-0000-0000-0000-000000000008', '128', 'حدثنا  معاوية بن عمرو  حدثنا  زائدة  حدثنا  عاصم  وحسين بن علي  عن  زائدة  عن  عاصم  عن  زر  عن  عبد الله  قال  لما قبض رسول الله  صلى الله عليه وسلم  قالت  الأنصار  منا أمير ومنكم أمير فأتاهم  عمر  رضي الله عنه  فقال يا معشر  الأنصار  ألستم تعلمون أن رسول الله  صلى الله عليه وسلم  قد  أمر  أبا بكر  رضي الله عنه  أن يؤم الناس فأيكم تطيب نفسه أن يتقدم  أبا بكر  رضي الله عنه  فقالت  الأنصار  نعوذ بالله أن نتقدم  أبا بكر  رضي الله عنه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c392958d-7d42-55bd-9dd3-c318a9f4417d', 'aaaaaaaa-0000-0000-0000-000000000008', '129', 'حدثنا  موسى بن داود  حدثنا  ابن لهيعة  عن  أبي الزبير  عن  جابر  أن  عمر بن الخطاب  رضي الله عنه  أخبره أنه  رأى رجلا توضأ للصلاة فترك موضع ظفر على ظهر قدمه فأبصره النبي  صلى الله عليه وسلم  فقال  ارجع فأحسن وضوءك فرجع فتوضأ ثم صلى', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f6934f74-5271-5f22-ba59-790b0ad9ec36', 'aaaaaaaa-0000-0000-0000-000000000008', '130', 'حدثنا  أبو سعيد  مولى  بني هاشم  حدثنا  الهيثم بن رافع الطاطري  بصري  حدثني  أبو يحيى  رجل من أهل  مكة  عن  فروخ  مولى  عثمان  أن  عمر  رضي الله عنه  وهو يومئذ أمير المؤمنين خرج إلى المسجد فرأى طعاما منثورا فقال ما هذا الطعام فقالوا طعام  جلب  إلينا قال بارك الله فيه وفيمن  جلبه  قيل يا أمير المؤمنين فإنه قد  احتكر  قال ومن  احتكره  قالوا  فروخ  مولى  عثمان  وفلان  مولى  عمر  فأرسل إليهما فدعاهما فقال ما حملكما على  احتكار  طعام المسلمين قالا يا أمير المؤمنين نشتري بأموالنا ونبيع فقال  عمر  سمعت رسول الله  صلى الله عليه وسلم  يقول  من  احتكر  على المسلمين طعامهم ضربه الله بالإفلاس أو  بجذام  فقال  فروخ  عند ذلك يا أمير المؤمنين أعاهد الله وأعاهدك أن لا أعود في طعام أبدا وأما  مولى  عمر  فقال إنما نشتري بأموالنا ونبيع  قال  أبو يحيى  فلقد رأيت  مولى  عمر  مجذوما', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e77c76e0-9255-524a-8869-feb06e1ce4f3', 'aaaaaaaa-0000-0000-0000-000000000008', '131', 'حدثنا  أبو اليمان  أنبأنا  شعيب  عن  الزهري  حدثنا  سالم بن عبد الله  أن  عبد الله بن عمر  قال سمعت  عمر  يقول  كان النبي  صلى الله عليه وسلم  يعطيني العطاء فأقول أعطه أفقر إليه مني حتى أعطاني مرة مالا فقلت أعطه أفقر إليه مني فقال النبي  صلى الله عليه وسلم  خذه فتموله وتصدق به فما جاءك من هذا المال وأنت غير  مشرف  ولا سائل فخذه وما لا فلا تتبعه نفسك  حدثنا  هارون  حدثنا  ابن وهب  أخبرني  يونس  عن  ابن شهاب  عن  سالم  عن  أبيه  قال سمعت  عمر  يقول  كان رسول الله  صلى الله عليه وسلم  يعطيني العطاء  فذكر معناه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3aff11d3-9b23-5851-bd0a-c8d882c71fc1', 'aaaaaaaa-0000-0000-0000-000000000008', '132', 'حدثنا  حجاج  حدثنا  ليث  حدثني  بكير  عن  عبد الملك بن سعيد الأنصاري  عن  جابر بن عبد الله  عن  عمر بن الخطاب  رضي الله عنه  قال  هششت  يوما فقبلت وأنا صائم فأتيت النبي  صلى الله عليه وسلم  فقلت صنعت اليوم أمرا عظيما فقبلت وأنا صائم فقال رسول الله  صلى الله عليه وسلم  أرأيت لو تمضمضت بماء وأنت صائم قلت لا بأس بذلك فقال رسول الله  صلى الله عليه وسلم  ففيم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('51052a11-37cb-5167-bac5-0210f5541ba2', 'aaaaaaaa-0000-0000-0000-000000000008', '133', 'حدثنا  يونس بن محمد  حدثنا  داود يعني ابن أبي الفرات  عن  عبد الله بن بريدة  عن  أبي الأسود  أنه قال  أتيت  المدينة  فوافيتها وقد وقع فيها مرض فهم  يموتون موتا ذريعا فجلست إلى  عمر بن الخطاب  رضي الله عنه  فمرت به جنازة فأثني على صاحبها خيرا فقال  عمر  رضي الله عنه  وجبت ثم مر بأخرى فأثني على صاحبها خيرا فقال  عمر  رضي الله عنه  وجبت ثم مر بالثالثة فأثني عليها شرا فقال  عمر  رضي الله عنه  وجبت فقال  أبو الأسود  ما وجبت يا أمير المؤمنين قال قلت كما قال رسول الله  صلى الله عليه وسلم  أيما مسلم شهد له أربعة بخير أدخله الله الجنة قال فقلنا وثلاثة قال فقال وثلاثة قال قلنا واثنان قال واثنان قال ثم لم نسأله عن الواحد', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3dab4488-27ad-5076-a5c3-b1d3a6e9ce57', 'aaaaaaaa-0000-0000-0000-000000000008', '134', 'حدثنا  أبو سعيد  حدثنا  ابن لهيعة  حدثنا  بكير  عن  سعيد بن المسيب  عن  عمر  قال  غزونا مع رسول الله  صلى الله عليه وسلم  في رمضان والفتح في رمضان فأفطرنا فيهما', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c5b72b3d-8a7b-5112-8701-e506a58b638b', 'aaaaaaaa-0000-0000-0000-000000000008', '135', 'حدثنا  أبو سعيد  مولى  بني هاشم  حدثنا  المثنى بن عوف العنزي  بصري  قال أنبأنا  الغضبان بن حنظلة  أن أباه  حنظلة بن نعيم  وفد إلى  عمر  فكان  عمر  إذا مر به إنسان من الوفد سأله ممن هو حتى مر به أبي فسأله ممن أنت فقال من  عنزة  فقال سمعت رسول الله  صلى الله عليه وسلم  يقول  حي من هاهنا  مبغي  عليهم منصورون', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3b2432e5-abe6-5eaf-b89c-bb25a5a2cd36', 'aaaaaaaa-0000-0000-0000-000000000008', '136', 'حدثنا  حسن بن موسى  حدثنا  ابن لهيعة  قال حدثنا  يزيد بن أبي حبيب  عن  معمر  أنه سأل  سعيد بن المسيب  عن الصيام في السفر  فحدثه عن  عمر بن الخطاب  رضي الله عنه  أنه قال  غزونا مع رسول الله  صلى الله عليه وسلم  غزوتين في شهر رمضان يوم  بدر  ويوم الفتح فأفطرنا فيهما', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b0fafcd-6a97-58f7-8a46-4a2bf6b77b50', 'aaaaaaaa-0000-0000-0000-000000000008', '137', 'حدثنا  أبو سعيد  حدثنا  ديلم بن غزوان عبدي  حدثنا  ميمون الكردي  حدثني  أبو عثمان النهدي  عن  عمر بن الخطاب  رضي الله عنه  أن رسول الله  صلى الله عليه وسلم  قال  إن أخوف ما أخاف على أمتي كل منافق عليم اللسان', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('825843f7-8ac5-587e-9f67-71d0a7a107b9', 'aaaaaaaa-0000-0000-0000-000000000008', '138', 'حدثنا  أبو سعيد  حدثنا  عبد العزيز بن محمد  حدثنا  صالح بن محمد بن زائدة  عن  سالم بن عبد الله  أنه كان مع  مسلمة بن عبد الملك  في أرض  الروم  فوجد في متاع رجل  غلول  فسأل  سالم بن عبد الله  فقال حدثني  عبد الله  عن  عمر  رضي الله عنه  أن رسول الله  صلى الله عليه وسلم  قال  من وجدتم في متاعه  غلولا  فأحرقوه  قال وأحسبه قال واضربوه  قال فأخرج متاعه في السوق قال فوجد فيه مصحفا فسأل  سالما  فقال بعه  وتصدق  بثمنه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b095974c-ad31-5c77-81f9-20d4f9403065', 'aaaaaaaa-0000-0000-0000-000000000008', '139', 'حدثنا  أبو سعيد  وحسين بن محمد  قالا حدثنا  إسرائيل  عن  أبي إسحاق  عن  عمرو بن ميمون  عن  عمر  رضي الله عنه  أن النبي  صلى الله عليه وسلم  كان  يتعوذ من خمس من البخل والجبن  وفتنة  الصدر وعذاب القبر وسوء العمر', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fbd05ec6-dad5-5420-9ac1-4dc9a81224c9', 'aaaaaaaa-0000-0000-0000-000000000008', '140', 'حدثنا  أبو سعيد  حدثنا  ابن لهيعة  قال سمعت  عطاء بن دينار  عن  أبي يزيد الخولاني  أنه سمع  فضالة بن عبيد  يقول سمعت  عمر بن الخطاب  رضي الله عنه  أنه سمع رسول الله  صلى الله عليه وسلم  يقول  الشهداء ثلاثة رجل مؤمن جيد الإيمان لقي العدو فصدق الله حتى قتل فذلك الذي يرفع إليه الناس أعناقهم يوم القيامة ورفع رسول الله  صلى الله عليه وسلم  رأسه حتى وقعت  قلنسوته  أو  قلنسوة  عمر  ورجل مؤمن جيد الإيمان لقي العدو فكأنما  يضرب  جلده بشوك  الطلح  أتاه سهم  غرب  فقتله هو في الدرجة الثانية ورجل مؤمن جيد الإيمان خلط عملا صالحا وآخر سيئا لقي العدو فصدق الله حتى قتل فذلك في الدرجة الثالثة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2b99c47b-a667-5784-a46c-a90a9286a25c', 'aaaaaaaa-0000-0000-0000-000000000008', '141', 'حدثنا  أبو سعيد  حدثنا  عبد الله بن لهيعة  حدثنا  عمرو بن شعيب  عن  أبيه  عن  جده  عن  عمر  رضي الله عنه  أن رسول الله  صلى الله عليه وسلم  قال  لا  يقاد  والد من ولد', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('232f2c73-cc14-534f-bce0-d7daa57ea51f', 'aaaaaaaa-0000-0000-0000-000000000008', '142', 'وقال رسول الله  صلى الله عليه وسلم  يرث المال من يرث  الولاء', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('71150cf3-6349-504f-b817-adfffa96b472', 'aaaaaaaa-0000-0000-0000-000000000008', '143', 'حدثنا  حسن  حدثنا  ابن لهيعة  حدثنا  عمرو بن شعيب  عن  أبيه  عن  عبد الله بن عمرو  رضي الله عنه  قال قال  عمر بن الخطاب  رضي الله عنه  سمعت رسول الله  صلى الله عليه وسلم  يقول  لا  يقاد  لولد  من والده', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a81dd4bf-ba05-5cb9-bb64-431eac562c3f', 'aaaaaaaa-0000-0000-0000-000000000008', '144', 'حدثنا  حسن  حدثنا  ابن لهيعة  حدثنا  الضحاك بن شرحبيل  عن  زيد بن أسلم  عن  أبيه  عن  عمر بن الخطاب  رضي الله عنه  أنه قال  رأيت رسول الله  صلى الله عليه وسلم  توضأ مرة مرة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('216b38fe-dea0-5927-ab1f-af5ac9fbc3a7', 'aaaaaaaa-0000-0000-0000-000000000008', '145', 'حدثنا  يحيى بن إسحاق  أنبأنا  ابن لهيعة  عن  عطاء بن دينار  عن  أبي يزيد الخولاني  قال سمعت  فضالة بن عبيد  يقول سمعت  عمر بن الخطاب  رضي الله عنه  يقول  سمعت رسول الله  صلى الله عليه وسلم  يقول  الشهداء أربعة رجل مؤمن جيد الإيمان لقي العدو فصدق الله فقتل فذلك الذي ينظر الناس إليه هكذا ورفع رأسه حتى سقطت  قلنسوة  رسول الله  صلى الله عليه وسلم  أو  قلنسوة  عمر  والثاني رجل مؤمن لقي العدو فكأنما  يضرب  ظهره بشوك  الطلح  جاءه سهم  غرب  فقتله فذاك في الدرجة الثانية والثالث رجل مؤمن خلط عملا صالحا وآخر سيئا لقي العدو فصدق الله عز وجل حتى قتل قال فذاك في الدرجة الثالثة والرابع رجل مؤمن أسرف على نفسه إسرافا كثيرا لقي العدو فصدق الله حتى قتل فذاك في الدرجة الرابعة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('15b5432e-1e26-5033-a482-aa7ccefd4168', 'aaaaaaaa-0000-0000-0000-000000000008', '146', 'حدثنا  يحيى بن غيلان  حدثنا  رشدين بن سعد  حدثني  أبو عبد الله الغافقي  عن  زيد بن أسلم  عن  أبيه  عن  عمر بن الخطاب  رضي الله عنه  عن رسول الله  صلى الله عليه وسلم  أنه  توضأ عام  تبوك  واحدة واحدة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('823a551b-0267-5c22-8684-1d707dccb92c', 'aaaaaaaa-0000-0000-0000-000000000008', '147', 'حدثنا  حسن  حدثنا  ابن لهيعة  حدثنا  أبو الزبير  عن  جابر  أن  عمر بن الخطاب  رضي الله عنه  أخبره أنه  سمع رسول الله  صلى الله عليه وسلم  يقول  سيخرج أهل  مكة  ثم لا يعبر بها  أو لا يعرفها إلا قليل  ثم تمتلئ  وتبنى ثم يخرجون منها فلا يعودون فيها أبدا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0bb139c1-04dc-5406-97da-594181b146ca', 'aaaaaaaa-0000-0000-0000-000000000008', '148', 'حدثنا  الحسن  حدثنا  ابن لهيعة  حدثنا  أبو الزبير  عن  جابر  أن  عمر بن الخطاب  رضي الله عنه  أخبره  أن رسول الله  صلى الله عليه وسلم  رأى رجلا توضأ لصلاة الظهر فترك موضع ظفر على ظهر قدمه فأبصره رسول الله  صلى الله عليه وسلم  فقال  ارجع فأحسن وضوءك فرجع فتوضأ ثم صلى', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cc219359-cb6b-5b16-a6b3-eb90d05be170', 'aaaaaaaa-0000-0000-0000-000000000008', '149', 'حدثنا  هشيم  قال  زعم  الزهري  عن  عبيد الله بن عبد الله بن عتبة بن مسعود  عن  ابن عباس  عن  عمر  رضي الله عنه  أن رسول الله  صلى الله عليه وسلم  قال  لا  تطروني  كما  أطرت  النصارى  عيسى ابن مريم  عليه السلام  فإنما أنا عبد الله ورسوله', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bab46ed2-0b44-566c-9b03-b9ee95d12666', 'aaaaaaaa-0000-0000-0000-000000000008', '150', 'حدثنا  هشيم  أنبأنا  أبو بشر  عن  سعيد بن جبير  عن  ابن عباس  قال  نزلت هذه الآية ورسول الله  صلى الله عليه وسلم  متوار  بمكة  { ولا تجهر بصلاتك ولا تخافت بها } قال كان  إذا صلى بأصحابه رفع صوته بالقرآن قال فلما سمع ذلك المشركون سبوا القرآن ومن أنزله ومن جاء به فقال الله عز وجل لنبيه  صلى الله عليه وسلم  { ولا تجهر بصلاتك } أي بقراءتك فيسمع المشركون فيسبوا القرآن  { ولا تخافت بها } عن أصحابك فلا تسمعهم القرآن حتى يأخذوه عنك  { وابتغ بين ذلك سبيلا }', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c1880ead-bd55-546c-a0fa-7efd915f84c9', 'aaaaaaaa-0000-0000-0000-000000000008', '151', 'حدثنا  هشيم  أنبأنا  علي بن زيد  عن  يوسف بن مهران  عن  ابن عباس  قال  خطب  عمر بن الخطاب  رضي الله عنه  وقال  هشيم  مرة خطبنا  فحمد الله تعالى وأثنى عليه فذكر  الرجم  فقال لا تخدعن عنه فإنه  حد  من  حدود  الله تعالى ألا إن رسول الله  صلى الله عليه وسلم  قد  رجم  ورجمنا  بعده ولولا أن يقول قائلون زاد  عمر  في كتاب الله ما ليس منه لكتبته في ناحية من المصحف شهد  عمر بن الخطاب  رضي الله عنه  وقال  هشيم  مرة  وعبد الرحمن بن عوف  وفلان وفلان  أن رسول الله  صلى الله عليه وسلم  قد  رجم  ورجمنا  من بعده ألا وإنه سيكون من بعدكم قوم يكذبون  بالرجم  وبالدجال  وبالشفاعة  وبعذاب القبر وبقوم يخرجون من النار بعدما  امتحشوا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ca9e76d8-af81-535f-9305-6ee02c21475f', 'aaaaaaaa-0000-0000-0000-000000000008', '152', 'حدثنا  هشيم  أنبأنا  حميد  عن  أنس  قال قال  عمر  رضي الله عنه  وافقت ربي في ثلاث قلت يا رسول الله  لو اتخذنا من  مقام  إبراهيم  مصلى فنزلت  { واتخذوا من  مقام  إبراهيم  مصلى } وقلت يا رسول الله إن نساءك يدخل عليهن  البر  والفاجر  فلو أمرتهن أن يحتجبن فنزلت  آية الحجاب  واجتمع على رسول الله  صلى الله عليه وسلم  نساؤه في الغيرة فقلت لهن  { عسى ربه إن طلقكن أن يبدله أزواجا خيرا منكن } قال فنزلت كذلك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b56f7532-a12b-5725-857b-1bb044f21fb6', 'aaaaaaaa-0000-0000-0000-000000000008', '153', 'حدثنا  عبد الأعلى بن عبد الأعلى  عن  معمر  عن  الزهري  عن  عروة بن الزبير  عن  المسور بن مخرمة  أن  عمر بن الخطاب  رضي الله عنه  قال  سمعت  هشام بن حكيم بن حزام  يقرأ سورة  الفرقان  فقرأ فيها  حروفا  لم يكن نبي الله  صلى الله عليه وسلم  أقرأنيها قال فأردت أن  أساوره  وهو  في الصلاة فلما فرغ قلت من أقرأك هذه القراءة قال رسول الله  صلى الله عليه وسلم  قلت كذبت والله ما هكذا أقرأك رسول الله  صلى الله عليه وسلم  فأخذت بيده أقوده فانطلقت به إلى رسول الله  صلى الله عليه وسلم  فقلت يا رسول الله إنك أقرأتني سورة  الفرقان  وإني سمعت هذا يقرأ فيها حروفا لم تكن أقرأتنيها فقال رسول الله  صلى الله عليه وسلم  اقرأ يا  هشام  فقرأ كما كان قرأ فقال رسول الله  صلى الله عليه وسلم  هكذا أنزلت ثم قال اقرأ يا  عمر  فقرأت فقال هكذا أنزلت ثم قال رسول الله  صلى الله عليه وسلم  إن القرآن نزل على سبعة  أحرف', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('07eb212c-4eaa-5d40-a489-764c73f6f6da', 'aaaaaaaa-0000-0000-0000-000000000008', '154', 'حدثنا  عمرو بن الهيثم  حدثنا  شعبة  عن  سماك بن حرب  عن  النعمان بن بشير  عن  عمر  قال  لقد رأيت رسول الله  صلى الله عليه وسلم  يلتوي ما يجد ما يملأ به بطنه من  الدقل', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('50c477f0-98cc-5c32-85ef-e870e854b790', 'aaaaaaaa-0000-0000-0000-000000000008', '155', 'حدثنا  ابن أبي عدي  عن  حميد  عن  أنس  قال قال  عمر  وافقت ربي عز وجل في ثلاث  أو وافقني ربي في ثلاث  قال قلت يا رسول الله لو اتخذت  المقام  مصلى قال فأنزل الله عز وجل  { واتخذوا من  مقام  إبراهيم  مصلى } وقلت لو حجبت عن  أمهات المؤمنين فإنه يدخل عليك  البر  والفاجر  فأنزلت  آية الحجاب  قال وبلغني عن  أمهات المؤمنين شيء فاستقريتهن أقول لهن لتكفن عن رسول الله  صلى الله عليه وسلم  أو ليبدلنه الله بكن أزواجا خيرا منكن مسلمات حتى أتيت على إحدى  أمهات المؤمنين فقالت يا  عمر  أما في رسول الله  صلى الله عليه وسلم  ما يعظ نساءه حتى تعظهن فكففت فأنزل الله عز وجل  { عسى ربه إن طلقكن أن يبدله أزواجا خيرا منكن مسلمات مؤمنات قانتات } الآية', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('72e361bb-592e-5dc8-b91f-fb9edb1b4b93', 'aaaaaaaa-0000-0000-0000-000000000008', '156', 'حدثنا  الوليد بن مسلم  حدثنا  الأوزاعي  أن  يحيى بن أبي كثير  حدثه عن  عكرمة  مولى  ابن عباس  قال سمعت  ابن عباس  يقول سمعت  عمر بن الخطاب  رضي الله عنه  يقول  سمعت رسول الله  صلى الله عليه وسلم  وهو  بالعقيق  يقول  أتاني الليلة آت من ربي فقال صل في هذا  الوادي  المبارك وقل عمرة في حجة  قال  الوليد  يعني  ذا الحليفة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f8ba52cd-f8dc-51e3-bd86-e0464cb3b1ef', 'aaaaaaaa-0000-0000-0000-000000000008', '157', 'حدثنا  سفيان  عن  الزهري  سمع  مالك بن أوس بن الحدثان  سمع  عمر بن الخطاب  رضي الله عنه  يقول  قال رسول الله  صلى الله عليه وسلم  وقال  سفيان  مرة سمع رسول الله  صلى الله عليه وسلم  يقول  الذهب  بالورق  ربا  إلا هاء وهاء  والبر  بالبر  ربا  إلا هاء وهاء والشعير بالشعير  ربا  إلا هاء وهاء والتمر بالتمر  ربا  إلا هاء وهاء', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bd58d218-bd5c-5fdd-bf28-b4da9544bc8d', 'aaaaaaaa-0000-0000-0000-000000000008', '158', 'حدثنا  سفيان  عن  الزهري  سمع  أبا عبيد  قال  شهدت العيد مع  عمر  فبدأ بالصلاة قبل الخطبة وقال إن رسول الله  صلى الله عليه وسلم  نهى عن صيام هذين اليومين أما يوم الفطر ففطركم من صومكم وأما يوم الأضحى فكلوا من لحم  نسككم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0c57bc82-b46d-558f-84f5-b6a56033dec3', 'aaaaaaaa-0000-0000-0000-000000000008', '159', 'حدثنا  سفيان  عن  الزهري  عن  عبيد الله بن عبد الله بن عتبة  عن  ابن عباس  عن  عمر  قال  قال رسول الله  صلى الله عليه وسلم  لا  تطروني  كما  أطرت  النصارى  عيسى ابن مريم  عليه السلام  فإنما أنا عبد فقولوا عبده ورسوله', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('726e58dc-89aa-55c1-ad15-99c23c03da41', 'aaaaaaaa-0000-0000-0000-000000000008', '160', 'حدثنا  سفيان  عن  عبد الله بن دينار  عن  ابن عمر  عن  عمر  أنه  سأل النبي  صلى الله عليه وسلم  أينام أحدنا وهو جنب قال يتوضأ وينام إن شاء  وقال  سفيان  مرة ليتوضأ ولينم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9d39f68a-49b8-5c53-9ab4-6d60e1c7e4bd', 'aaaaaaaa-0000-0000-0000-000000000008', '161', 'حدثنا  سفيان  عن  زيد بن أسلم  عن  أبيه  أن  عمر  حمل على فرس في سبيل الله فرآها  أو بعض نتاجها  يباع فأراد شراءه فسأل النبي  صلى الله عليه وسلم  عنه فقال  اتركها توافك أو تلقها جميعا وقال مرتين فنهاه وقال لا تشتره ولا تعد في  صدقتك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('908096f4-676e-5628-a9e7-1ec85f063dab', 'aaaaaaaa-0000-0000-0000-000000000008', '162', 'حدثنا  سفيان  عن  عاصم بن عبيد الله  عن  عبد الله بن عامر بن ربيعة  يحدث عن  عمر  رضي الله عنه  يبلغ به النبي  وقال  سفيان  مرة عن النبي  صلى الله عليه وسلم  قال  تابعوا بين الحج والعمرة فإن متابعة بينهما ينفيان الفقر والذنوب كما ينفي  الكير  خبث  الحديد', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fabf6d7d-23d6-59ab-b06b-c4127a288dd6', 'aaaaaaaa-0000-0000-0000-000000000008', '163', 'حدثنا  سفيان  عن  يحيى  عن  محمد بن إبراهيم التيمي  عن  علقمة بن وقاص  قال سمعت  عمر  رضي الله عنه  يقول  سمعت رسول الله  صلى الله عليه وسلم  يقول  إنما الأعمال بالنية ولكل امرئ ما نوى فمن كانت هجرته إلى الله عز وجل فهجرته إلى ما هاجر إليه ومن كانت هجرته لدنيا  يصيبها  أو امرأة ينكحها فهجرته إلى ما هاجر إليه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('288b2863-14c0-5718-8bf1-ea45c4d89506', 'aaaaaaaa-0000-0000-0000-000000000008', '164', 'حدثنا  سفيان  عن  عبدة بن أبي لبابة  عن  أبي وائل  قال قال  الصبي بن معبد  كنت رجلا نصرانيا فأسلمت  فأهللت  بالحج والعمرة فسمعني  زيد بن صوحان  وسلمان بن ربيعة  وأنا  أهل  بهما فقالا لهذا أضل من بعير أهله فكأنما حمل علي بكلمتهما جبل فقدمت على  عمر  رضي الله عنه  فأخبرته فأقبل عليهما فلامهما وأقبل علي فقال  هديت لسنة النبي  صلى الله عليه وسلم  هديت لسنة نبيك  صلى الله عليه وسلم  قال  عبدة  قال  أبو وائل  كثيرا ما ذهبت أنا  ومسروق  إلى  الصبي  نسأله عنه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ed6659d1-6342-5863-893e-39ebe14429c6', 'aaaaaaaa-0000-0000-0000-000000000008', '165', 'حدثنا  سفيان  عن  عمرو  عن  طاوس  عن  ابن عباس  ذكر  لعمر  أن  سمرة  وقال مرة بلغ  عمر  رضي الله عنه  أن  سمرة  باع خمرا قال قاتل الله  سمرة  إن رسول الله  صلى الله عليه وسلم  قال  لعن الله  اليهود  حرمت عليهم الشحوم  فجملوها  فباعوها', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('db4344da-be99-5ec0-aa2d-453ae3984520', 'aaaaaaaa-0000-0000-0000-000000000008', '166', 'حدثنا  سفيان  عن  عمرو  ومعمر  عن  الزهري  عن  مالك بن أوس بن الحدثان  عن  عمر بن الخطاب  رضي الله عنه  قال  كانت أموال  بني النضير  مما  أفاء  الله على رسوله  صلى الله عليه وسلم  مما لم  يوجف  المسلمون عليه بخيل ولا ركاب فكانت لرسول الله  صلى الله عليه وسلم  خالصة وكان ينفق على أهله منها نفقة سنة  وقال  مرة  قوت  سنة  وما بقي جعله في  الكراع  والسلاح عدة في سبيل الله عز وجل', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dfed9f48-c9cf-583e-8717-f810b80294e5', 'aaaaaaaa-0000-0000-0000-000000000008', '167', 'حدثنا  سفيان  عن  عمرو  عن  الزهري  عن  مالك بن أوس  قال  سمعت  عمر  رضي الله عنه  يقول  لعبد الرحمن بن عوف  وطلحة  والزبير  وسعد  نشدتكم بالله الذي تقوم السماء والأرض به أعلمتم أن رسول الله  صلى الله عليه وسلم  قال إنا  لا نورث ما تركنا  صدقة  قالوا اللهم نعم', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('968feefb-9dbe-50b7-a657-b77fae8784c1', 'aaaaaaaa-0000-0000-0000-000000000008', '168', 'حدثنا  سفيان  عن  ابن أبي يزيد  عن  أبيه  عن  عمر بن الخطاب  رضي الله عنه  أن رسول الله  صلى الله عليه وسلم  قال  الولد  للفراش', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a430bcb1-796c-543c-b904-8a5490120ef0', 'aaaaaaaa-0000-0000-0000-000000000008', '169', 'حدثنا  ابن إدريس  أنبأنا  ابن جريج  عن  ابن أبي عمار  عن  عبد الله بن بابيه  عن  يعلى بن أمية  قال  سألت  عمر بن الخطاب  قلت  { ليس عليكم  جناح  أن تقصروا من الصلاة إن خفتم أن يفتنكم الذين كفروا } وقد أمن الله الناس فقال لي  عمر  عجبت مما عجبت منه فسألت رسول الله  صلى الله عليه وسلم  عن ذلك فقال  صدقة  تصدق الله بها عليكم فاقبلوا صدقته', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fb7976ec-cd7b-5330-b2e2-fde656beefb8', 'aaaaaaaa-0000-0000-0000-000000000008', '170', 'حدثنا  أبو معاوية  حدثنا  الأعمش  عن  إبراهيم  عن  علقمة  قال  جاء رجل إلى  عمر  رضي الله عنه  وهو  بعرفة  قال  أبو معاوية  وحدثنا  الأعمش  عن  خيثمة  عن  قيس بن مروان  أنه أتى  عمر  رضي الله عنه  فقال جئت يا أمير المؤمنين من  الكوفة  وتركت بها رجلا  يملي  المصاحف عن ظهر قلبه فغضب وانتفخ حتى كاد يملأ  ما بين  شعبتي  الرحل فقال ومن هو  ويحك  قال  عبد الله بن مسعود  فما زال يطفأ  ويسرى عنه الغضب حتى عاد إلى حاله التي كان عليها ثم قال  ويحك  والله ما أعلمه بقي من الناس أحد هو أحق بذلك منه وسأحدثك عن ذلك كان رسول الله  صلى الله عليه وسلم  لا يزال  يسمر  عند  أبي بكر  رضي الله عنه  الليلة كذاك في الأمر من أمر المسلمين وإنه  سمر  عنده ذات ليلة وأنا معه فخرج رسول الله  صلى الله عليه وسلم  وخرجنا معه فإذا رجل قائم  يصلي في المسجد فقام رسول الله  صلى الله عليه وسلم  يستمع قراءته فلما كدنا أن نعرفه قال رسول الله  صلى الله عليه وسلم  من سره أن يقرأ القرآن رطبا كما أنزل فليقرأه على قراءة  ابن أم عبد  قال ثم جلس الرجل يدعو فجعل رسول الله  صلى الله عليه وسلم  يقول له  سل  تعطه  سل  تعطه  قال  عمر  رضي الله عنه  قلت والله  لأغدون  إليه فلأبشرنه قال  فغدوت  إليه لأبشره فوجدت  أبا بكر  قد سبقني إليه فبشره ولا والله ما سبقته إلى خير قط إلا وسبقني إليه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bdc77a03-bd66-5a18-aafa-ac18111fabaa', 'aaaaaaaa-0000-0000-0000-000000000008', '171', 'حدثنا  أبو معاوية  قال حدثنا  الأعمش  عن  إبراهيم  عن  عابس بن ربيعة  قال  رأيت  عمر  رضي الله عنه  يقبل الحجر ويقول إني لأقبلك وأعلم أنك حجر ولولا أني رأيت رسول الله  صلى الله عليه وسلم  يقبلك لم أقبلك', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8d2f568b-281e-5c9b-b6f9-3d1ad03abac4', 'aaaaaaaa-0000-0000-0000-000000000008', '172', 'حدثنا  جرير  عن  عبد الملك بن عمير  عن  جابر بن سمرة  قال  خطب  عمر  الناس  بالجابية  فقال إن رسول الله  صلى الله عليه وسلم  قام في مثل مقامي هذا فقال  أحسنوا إلى أصحابي ثم الذين يلونهم ثم الذين يلونهم ثم يجيء قوم يحلف أحدهم على اليمين قبل أن يستحلف عليها ويشهد على الشهادة قبل أن يستشهد فمن أحب منكم أن ينال  بحبوحة  الجنة فليلزم الجماعة فإن الشيطان مع الواحد وهو من  الاثنين أبعد ولا يخلون رجل بامرأة فإن ثالثهما الشيطان ومن كان منكم تسره حسنته وتسوءه سيئته فهو مؤمن', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aa9d11b3-1a17-53c2-a1a5-6e764e9d166b', 'aaaaaaaa-0000-0000-0000-000000000008', '173', 'حدثنا  أبو معاوية  حدثنا  الأعمش  عن  إبراهيم  عن  علقمة  عن  عمر  رضي الله عنه  قال  كان رسول الله  صلى الله عليه وسلم  يسمر  عند  أبي بكر  الليلة كذلك في الأمر من أمر المسلمين وأنا معه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2477cab0-1edd-572c-9f5c-b6ecee749fb5', 'aaaaaaaa-0000-0000-0000-000000000008', '174', 'حدثنا  إسماعيل  عن  سعيد بن أبي عروبة  عن  قتادة  عن  سالم بن أبي الجعد  عن  معدان بن أبي طلحة  قال قال  عمر  رضي الله عنه  ما سألت رسول الله  صلى الله عليه وسلم  عن شيء أكثر مما سألته عن  الكلالة  حتى  طعن  بإصبعه في صدري وقال  تكفيك  آية الصيف  التي في آخر سورة  النساء', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b3895802-a47d-5c07-91ff-74424af967d0', 'aaaaaaaa-0000-0000-0000-000000000008', '175', 'حدثنا  يحيى  حدثنا  شعبة  حدثنا  قتادة  عن  سعيد بن المسيب  عن  ابن عمر  عن  عمر  رضي الله عنهما  عن النبي  صلى الله عليه وسلم  قال  الميت يعذب في قبره  بالنياحة  عليه', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('64cf6ad1-6574-5c8a-b560-a9a6c2745d62', 'aaaaaaaa-0000-0000-0000-000000000008', '176', 'حدثنا  يحيى  عن  عبد الملك  حدثنا  عبد الله  مولى  أسماء  قال  أرسلتني  أسماء  إلى  ابن عمر  أنه بلغها أنك تحرم أشياء ثلاثة  العلم  في الثوب  وميثرة  الأرجوان  وصوم رجب كله فقال أما ما ذكرت من صوم رجب فكيف بمن يصوم الأبد وأما ما ذكرت من  العلم  في الثوب فإني سمعت  عمر  رضي الله عنه  يقول سمعت رسول الله  صلى الله عليه وسلم  يقول  من لبس الحرير في الدنيا لم يلبسه في الآخرة', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f91de79e-8c97-506f-823c-b493d3da84e1', 'aaaaaaaa-0000-0000-0000-000000000008', '177', 'حدثنا  يحيى بن سعيد  وأنا سألته  حدثنا  سليمان بن المغيرة  حدثنا  ثابت  عن  أنس  قال  كنا مع  عمر  بين  مكة  والمدينة  فتراءينا الهلال وكنت  حديد البصر  فرأيته فجعلت أقول  لعمر  أما تراه قال  سأراه وأنا مستلق على فراشي ثم أخذ يحدثنا عن أهل  بدر  قال إن كان رسول الله  صلى الله عليه وسلم  ليرينا  مصارعهم  بالأمس يقول هذا  مصرع  فلان غدا إن شاء الله تعالى وهذا  مصرع  فلان غدا إن شاء الله تعالى قال فجعلوا  يصرعون  عليها قال قلت والذي بعثك بالحق ما أخطئوا تيك كانوا  يصرعون  عليها ثم أمر بهم  فطرحوا  في بئر فانطلق إليهم فقال يا فلان يا فلان  هل  وجدتم ما وعدكم الله حقا فإني وجدت ما وعدني الله حقا قال  عمر  يا رسول الله أتكلم قوما قد  جيفوا  قال ما أنتم بأسمع لما أقول منهم ولكن لا يستطيعون أن يجيبوا', 'مسند أحمد — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
